-- 013: Bổ sung khóa học để mỗi danh mục có ít nhất 10 khóa đang bán (dữ liệu dùng để demo / kiểm thử).
-- Mỗi khóa mới có 1 chương, 1 bài học (xem thử được), dùng chung video demo có sẵn trong repo
-- (assets/uploads/videos/vid_KH260929150333_20260930121911_38701957.mp4, 5 phút 17 giây).
-- Mô tả, mục tiêu đầu ra và tên bài học viết riêng cho từng khóa; ảnh bìa lấy từ Unsplash (đã kiểm tra đúng chủ đề).
--
-- Số khóa thêm tính theo dữ liệu trên máy đang chạy: danh mục đã có N khóa đang bán (không tính khóa của file này)
-- thì chỉ thêm (10 - N) khóa đầu danh sách của danh mục đó. Danh mục không tồn tại thì bỏ qua.
-- Mã khóa học dạng K13-<danh mục>-<số thứ tự>. Chạy lại được: không thêm trùng, không sửa dữ liệu cũ.
-- Cần chạy sau 012 (012 tạo các danh mục CAT-002..CAT-006 nếu máy chưa có).
-- Giáo viên: khoa.tran / ha.le / bao.pham (dữ liệu demo); máy chưa nạp dữ liệu demo thì dùng giáo viên đầu tiên.
USE QL_HETHONG_CUNGCAP_KHOAHOC;
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @GvMacDinh INT = (SELECT TOP 1 maNguoiDung FROM dbo.NguoiDung WHERE vaiTro = N'GiaoVien' ORDER BY maNguoiDung);
DECLARE @T1 INT = ISNULL((SELECT maNguoiDung FROM dbo.NguoiDung WHERE email = 'khoa.tran@demo.ecolearning.vn'), @GvMacDinh);
DECLARE @T2 INT = ISNULL((SELECT maNguoiDung FROM dbo.NguoiDung WHERE email = 'ha.le@demo.ecolearning.vn'), @GvMacDinh);
DECLARE @T3 INT = ISNULL((SELECT maNguoiDung FROM dbo.NguoiDung WHERE email = 'bao.pham@demo.ecolearning.vn'), @GvMacDinh);
DECLARE @Admin INT = (SELECT TOP 1 maNguoiDung FROM dbo.NguoiDung WHERE vaiTro = N'Admin' ORDER BY maNguoiDung);
DECLARE @Video VARCHAR(500) = '/assets/uploads/videos/vid_KH260929150333_20260930121911_38701957.mp4';
DECLARE @ThoiLuong INT = 317;

IF @GvMacDinh IS NULL
BEGIN
    RAISERROR(N'Chưa có tài khoản giáo viên nào: chạy Database/Seed/01_du_lieu_demo.sql hoặc tạo giáo viên trước.', 16, 1);
    RETURN;
END

DECLARE @K TABLE (
    ma VARCHAR(20) PRIMARY KEY, maDanhMuc VARCHAR(20), stt INT, gv CHAR(2),
    ten NVARCHAR(255), capDo NVARCHAR(50), giaBan DECIMAL(18, 2), giaKhuyenMai DECIMAL(18, 2) NULL,
    moTaNgan NVARCHAR(500), moTa NVARCHAR(MAX), mucTieu NVARCHAR(MAX), chuong NVARCHAR(200), bai NVARCHAR(200), anhBia VARCHAR(500));


-- Khóa sẽ thêm: đủ để danh mục đạt 10 khóa đang bán
DECLARE @Them TABLE (ma VARCHAR(20) PRIMARY KEY);
SELECT k.ma
FROM @K k
JOIN dbo.DanhMuc d ON d.maDanhMuc = k.maDanhMuc
CROSS APPLY (SELECT COUNT(*) AS n FROM dbo.KhoaHoc x
             WHERE x.maDanhMuc = k.maDanhMuc
               AND x.trangThai IN (N'Đã xuất bản', N'Đã duyệt', N'Active')
               AND x.maKhoaHoc NOT LIKE 'K13-%') co
WHERE k.stt <= 10 - co.n
  AND NOT EXISTS (SELECT 1 FROM dbo.KhoaHoc x WHERE x.maKhoaHoc = k.ma);

BEGIN TRANSACTION;

SELECT k.ma, k.ten, k.moTaNgan, k.moTa, k.mucTieu, k.giaBan, k.giaKhuyenMai, k.capDo, N'Đã xuất bản', k.maDanhMuc,
       CASE k.gv WHEN 'T1' THEN @T1 WHEN 'T2' THEN @T2 ELSE @T3 END, k.anhBia
FROM @K k JOIN @Them t ON t.ma = k.ma;

SELECT k.ma + '_C1', k.chuong, 1, k.ma
FROM @K k JOIN @Them t ON t.ma = k.ma;

SELECT k.ma + '_1', k.bai, @ThoiLuong, 1, k.ma + '_C1', @Video, 1
FROM @K k JOIN @Them t ON t.ma = k.ma;

-- Lịch sử duyệt (Admin đã duyệt), rải trong 3 tháng gần đây để mục "cập nhật" trên trang chi tiết có ngày hợp lý
SELECT 'KD13-' + SUBSTRING(k.ma, 5, 20),
       DATEADD(DAY, -(k.stt * 9 + LEN(k.maDanhMuc)) - 1, GETDATE()),
       DATEADD(DAY, -(k.stt * 9 + LEN(k.maDanhMuc)), GETDATE()),
       N'Đã duyệt', NULL, k.ma, @Admin
FROM @K k JOIN @Them t ON t.ma = k.ma
WHERE NOT EXISTS (SELECT 1 FROM dbo.KiemDuyetKhoaHoc x WHERE x.maKiemDuyet = 'KD13-' + SUBSTRING(k.ma, 5, 20));

COMMIT;

-- Kết quả: số khóa đang bán của từng danh mục sau khi chạy
SELECT d.maDanhMuc, d.tenDanhMuc,
       (SELECT COUNT(*) FROM @Them t JOIN @K k ON k.ma = t.ma WHERE k.maDanhMuc = d.maDanhMuc) AS soKhoaVuaThem,
       (SELECT COUNT(*) FROM dbo.KhoaHoc x WHERE x.maDanhMuc = d.maDanhMuc AND x.trangThai IN (N'Đã xuất bản', N'Đã duyệt', N'Active')) AS soKhoaDangBan
FROM dbo.DanhMuc d
ORDER BY d.maDanhMuc;
GO

