DELETE FROM dbo.BaiHoc WHERE maBaiHoc LIKE 'K13-%';
DELETE FROM dbo.ChuongHoc WHERE maKhoaHoc LIKE 'K13-%';
DELETE FROM dbo.KhoaHoc WHERE maKhoaHoc LIKE 'K13-%';
   (Khóa đã có người mua / đánh giá thì phải xóa các dòng liên quan trước.) */
