INSERT INTO @K VALUES
('K13-DM01-01', 'DM01', 1, 'T1', N'HTML & CSS từ con số 0', N'Cơ bản', 499000, 349000, N'Dựng trang web tĩnh đầu tiên với HTML5 và CSS3, hiểu Flexbox, Grid và responsive.', N'Khóa học dành cho người chưa từng viết code web. Bạn học cấu trúc tài liệu HTML5, các thẻ ngữ nghĩa, định dạng bằng CSS3, mô hình hộp, Flexbox, CSS Grid và media query. Cuối khóa bạn tự cắt một landing page hoàn chỉnh hiển thị tốt trên cả máy tính lẫn điện thoại.', N'Viết HTML5 đúng ngữ nghĩa; Dàn trang bằng Flexbox và CSS Grid; Làm giao diện responsive cho điện thoại; Tự cắt một landing page hoàn chỉnh', N'Chương 1: Làm quen với web', N'Bài 1: Trình duyệt hiển thị một trang web như thế nào', 'https://images.unsplash.com/photo-1542831371-29b0f74f9713?w=800&auto=format&fit=crop&q=80'),
('K13-DM01-02', 'DM01', 2, 'T1', N'ReactJS cho người mới bắt đầu', N'Trung cấp', 1190000, 790000, N'Xây dựng giao diện web hiện đại bằng React: component, props, state và hooks.', N'Khóa học đưa bạn từ JavaScript sang tư duy component của React. Bạn làm việc với JSX, props, state, useEffect, xử lý form, gọi API và điều hướng bằng React Router. Dự án cuối khóa là một ứng dụng quản lý công việc có lưu dữ liệu qua API.', N'Chia giao diện thành các component tái sử dụng; Quản lý state bằng useState và useEffect; Gọi API và hiển thị dữ liệu bất đồng bộ; Điều hướng nhiều trang với React Router', N'Chương 1: Tư duy component', N'Bài 1: Cài đặt dự án React với Vite', 'https://images.unsplash.com/photo-1607799279861-4dd421887fb3?w=800&auto=format&fit=crop&q=80'),
('K13-DM01-03', 'DM01', 3, 'T1', N'Node.js & Express: xây dựng REST API', N'Trung cấp', 1090000, NULL, N'Viết REST API bằng Node.js và Express, kết nối cơ sở dữ liệu và xác thực bằng JWT.', N'Bạn học cách Node.js xử lý bất đồng bộ, tổ chức dự án Express theo route, controller và middleware, kết nối MongoDB, kiểm tra dữ liệu đầu vào và xác thực người dùng bằng JWT. Khóa học kết thúc bằng việc viết tài liệu API và triển khai lên máy chủ.', N'Thiết kế REST API đúng chuẩn; Viết middleware xử lý lỗi và xác thực; Kết nối và truy vấn MongoDB; Bảo vệ API bằng JWT', N'Chương 1: Nền tảng Node.js', N'Bài 1: Event loop và lập trình bất đồng bộ trong Node.js', 'https://images.unsplash.com/photo-1518432031352-d6fc5c10da5a?w=800&auto=format&fit=crop&q=80'),
('K13-DM01-04', 'DM01', 4, 'T1', N'Git và GitHub cho lập trình viên', N'Cơ bản', 299000, 199000, N'Quản lý mã nguồn với Git, làm việc nhóm trên GitHub qua branch và pull request.', N'Khóa học ngắn giúp bạn dùng Git hằng ngày một cách tự tin: commit, branch, merge, rebase, xử lý xung đột, hoàn tác thay đổi và làm việc nhóm qua pull request trên GitHub. Mọi thao tác đều được thực hành trên một dự án mẫu.', N'Lưu lịch sử thay đổi bằng commit rõ ràng; Làm việc với branch và merge; Tự xử lý xung đột khi merge; Review code qua pull request trên GitHub', N'Chương 1: Git căn bản', N'Bài 1: Cài đặt Git và tạo repository đầu tiên', 'https://images.unsplash.com/photo-1556075798-4825dfaaf498?w=800&auto=format&fit=crop&q=80'),
('K13-DM01-05', 'DM01', 5, 'T1', N'ASP.NET Core Web API thực chiến', N'Nâng cao', 1390000, 990000, N'Xây dựng Web API với ASP.NET Core, Entity Framework Core và kiến trúc nhiều tầng.', N'Khóa học hướng dẫn xây dựng một Web API hoàn chỉnh trên .NET: cấu hình dependency injection, Entity Framework Core với migration, phân tầng repository và service, xác thực JWT, phân quyền theo vai trò, ghi log và viết unit test.', N'Tổ chức dự án theo kiến trúc nhiều tầng; Dùng Entity Framework Core và migration; Xác thực và phân quyền bằng JWT; Viết unit test cho tầng service', N'Chương 1: Khởi tạo dự án', N'Bài 1: Cấu trúc một dự án ASP.NET Core Web API', 'https://images.unsplash.com/photo-1587620962725-abab7fe55159?w=800&auto=format&fit=crop&q=80'),
('K13-DM01-06', 'DM01', 6, 'T1', N'Lập trình Java hướng đối tượng', N'Cơ bản', 799000, NULL, N'Học Java từ cú pháp đến lập trình hướng đối tượng và các cấu trúc dữ liệu thông dụng.', N'Khóa học trình bày cú pháp Java, kiểu dữ liệu, vòng lặp, mảng, sau đó đi sâu vào bốn tính chất của lập trình hướng đối tượng, interface, xử lý ngoại lệ và Collections Framework. Các bài tập được chấm theo từng chương.', N'Viết chương trình Java với IntelliJ IDEA; Áp dụng đóng gói kế thừa và đa hình; Dùng ArrayList và HashMap hiệu quả; Xử lý ngoại lệ đúng cách', N'Chương 1: Bắt đầu với Java', N'Bài 1: JDK, JVM và chương trình Java đầu tiên', 'https://images.unsplash.com/photo-1461749280684-dccba630e2f6?w=800&auto=format&fit=crop&q=80'),
('K13-DM01-07', 'DM01', 7, 'T1', N'Docker cho lập trình viên', N'Trung cấp', 990000, 690000, N'Đóng gói ứng dụng bằng Docker, viết Dockerfile và chạy nhiều dịch vụ với Docker Compose.', N'Bạn hiểu sự khác nhau giữa container và máy ảo, viết Dockerfile tối ưu dung lượng, quản lý image, volume, network và dùng Docker Compose để chạy ứng dụng web cùng cơ sở dữ liệu chỉ bằng một lệnh. Phần cuối giới thiệu đưa image lên registry.', N'Viết Dockerfile cho ứng dụng web; Quản lý volume và network; Chạy nhiều dịch vụ bằng Docker Compose; Đẩy image lên Docker Hub', N'Chương 1: Container là gì', N'Bài 1: Container khác máy ảo ở điểm nào', 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?w=800&auto=format&fit=crop&q=80'),
('K13-DM01-08', 'DM01', 8, 'T1', N'Flutter: phát triển ứng dụng di động', N'Trung cấp', 1290000, 890000, N'Viết ứng dụng Android và iOS từ một mã nguồn với Flutter và ngôn ngữ Dart.', N'Khóa học bắt đầu với ngôn ngữ Dart, sau đó xây dựng giao diện bằng widget, quản lý trạng thái với Provider, điều hướng nhiều màn hình, gọi API và lưu dữ liệu cục bộ. Dự án cuối khóa là ứng dụng ghi chú chạy trên cả Android và iOS.', N'Nắm cú pháp Dart cần cho Flutter; Dựng giao diện bằng widget; Quản lý trạng thái với Provider; Gọi API và lưu dữ liệu trên máy', N'Chương 1: Làm quen Flutter', N'Bài 1: Cài đặt Flutter SDK và chạy ứng dụng đầu tiên', 'https://images.unsplash.com/photo-1551650975-87deedd944c3?w=800&auto=format&fit=crop&q=80'),
('K13-DM01-09', 'DM01', 9, 'T1', N'Bảo mật ứng dụng web theo OWASP Top 10', N'Nâng cao', 1190000, NULL, N'Nhận diện và phòng chống các lỗ hổng web phổ biến nhất theo OWASP Top 10.', N'Khóa học phân tích từng nhóm lỗ hổng trong OWASP Top 10 như SQL Injection, XSS, CSRF, lỗi xác thực và cấu hình sai. Mỗi lỗ hổng được trình bày theo ba bước: cách khai thác trên ứng dụng thử nghiệm, nguyên nhân trong mã nguồn và cách sửa đúng.', N'Nhận diện các lỗ hổng trong OWASP Top 10; Phòng chống SQL Injection và XSS; Bảo vệ form khỏi tấn công CSRF; Rà soát bảo mật mã nguồn web', N'Chương 1: Tổng quan bảo mật web', N'Bài 1: OWASP Top 10 là gì và vì sao quan trọng', 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?w=800&auto=format&fit=crop&q=80'),
('K13-DM01-10', 'DM01', 10, 'T1', N'Linux căn bản cho lập trình viên', N'Cơ bản', 399000, 299000, N'Làm chủ dòng lệnh Linux: quản lý tệp, phân quyền, tiến trình và viết shell script.', N'Khóa học giúp lập trình viên làm việc thoải mái trên máy chủ Linux: di chuyển trong hệ thống tệp, phân quyền, quản lý gói phần mềm, theo dõi tiến trình, kết nối SSH và viết shell script tự động hóa các công việc lặp lại.', N'Thao tác tệp và thư mục bằng dòng lệnh; Hiểu phân quyền người dùng trên Linux; Kết nối máy chủ qua SSH; Viết shell script tự động hóa', N'Chương 1: Dòng lệnh Linux', N'Bài 1: Terminal và các lệnh di chuyển cơ bản', 'https://images.unsplash.com/photo-1605379399642-870262d3d051?w=800&auto=format&fit=crop&q=80'),
('K13-DM02-01', 'DM02', 1, 'T2', N'Nguyên lý UX và nghiên cứu người dùng', N'Cơ bản', 690000, 490000, N'Hiểu quy trình UX, phỏng vấn người dùng, xây persona và hành trình khách hàng.', N'Khóa học giới thiệu quy trình thiết kế lấy người dùng làm trung tâm: lập kế hoạch nghiên cứu, phỏng vấn, khảo sát, tổng hợp insight, xây dựng persona và bản đồ hành trình khách hàng. Bạn thực hành trên một bài toán thật của ứng dụng đặt đồ ăn.', N'Lập kế hoạch nghiên cứu người dùng; Phỏng vấn và tổng hợp insight; Xây dựng persona và hành trình khách hàng; Biến insight thành yêu cầu thiết kế', N'Chương 1: Tư duy UX', N'Bài 1: UX khác UI như thế nào', 'https://images.unsplash.com/photo-1581291518857-4e27b48ff24e?w=800&auto=format&fit=crop&q=80'),
('K13-DM02-02', 'DM02', 2, 'T2', N'Adobe Illustrator: thiết kế vector và logo', N'Cơ bản', 790000, NULL, N'Vẽ vector bằng Pen Tool, xử lý hình khối và thiết kế logo hoàn chỉnh trong Illustrator.', N'Bạn làm quen với artboard, công cụ Pen, Shape Builder, Pathfinder, màu sắc và chữ trong Adobe Illustrator. Phần thực hành hướng dẫn quy trình thiết kế logo từ phác thảo ý tưởng đến xuất file cho in ấn và cho web.', N'Vẽ đường cong chính xác bằng Pen Tool; Kết hợp hình khối bằng Shape Builder; Thiết kế logo từ phác thảo; Xuất file vector cho in ấn và web', N'Chương 1: Làm quen Illustrator', N'Bài 1: Artboard và các công cụ vẽ cơ bản', 'https://images.unsplash.com/photo-1626785774573-4b799315345d?w=800&auto=format&fit=crop&q=80'),
('K13-DM02-03', 'DM02', 3, 'T2', N'Design System với Figma', N'Nâng cao', 1290000, 890000, N'Xây dựng thư viện component, biến màu và typography dùng chung cho cả đội sản phẩm.', N'Khóa học dành cho người đã biết Figma, tập trung vào cách xây design system có thể mở rộng: design token, biến màu, kiểu chữ, component với variant và thuộc tính, quy ước đặt tên, tài liệu sử dụng và quy trình cập nhật thư viện cho cả đội.', N'Định nghĩa design token cho màu và chữ; Tạo component có variant và thuộc tính; Tổ chức thư viện dùng chung cho đội; Viết tài liệu hướng dẫn sử dụng component', N'Chương 1: Nền tảng Design System', N'Bài 1: Design System gồm những gì', 'https://images.unsplash.com/photo-1541462608143-67571c6738dd?w=800&auto=format&fit=crop&q=80'),
('K13-DM02-04', 'DM02', 4, 'T2', N'Thiết kế giao diện ứng dụng di động', N'Trung cấp', 990000, 690000, N'Thiết kế màn hình app theo chuẩn iOS và Material Design, từ wireframe đến bản hoàn thiện.', N'Bạn học các nguyên tắc riêng của giao diện di động: vùng chạm, điều hướng bằng tab, khoảng cách, lưới và trạng thái màn hình. Khóa học đi qua quy trình wireframe, giao diện chi tiết và bàn giao cho lập trình viên theo hướng dẫn của Apple và Google.', N'Áp dụng hướng dẫn giao diện của iOS và Android; Dựng wireframe cho luồng chính của app; Thiết kế đủ trạng thái của một màn hình; Bàn giao thiết kế cho lập trình viên', N'Chương 1: Đặc thù giao diện di động', N'Bài 1: Kích thước màn hình và vùng chạm', 'https://images.unsplash.com/photo-1609921212029-bb5a28e60960?w=800&auto=format&fit=crop&q=80'),
('K13-DM02-05', 'DM02', 5, 'T2', N'Thiết kế nhận diện thương hiệu', N'Trung cấp', 1090000, NULL, N'Xây dựng bộ nhận diện thương hiệu: logo, màu, chữ, hình ảnh và brand guideline.', N'Khóa học đi từ việc tìm hiểu thương hiệu, định vị và tính cách thương hiệu đến thiết kế logo, hệ màu, kiểu chữ, hình ảnh, ứng dụng trên ấn phẩm văn phòng và mạng xã hội. Sản phẩm cuối là một bộ brand guideline hoàn chỉnh.', N'Phân tích định vị và tính cách thương hiệu; Thiết kế hệ màu và kiểu chữ thương hiệu; Ứng dụng nhận diện trên nhiều ấn phẩm; Trình bày brand guideline chuyên nghiệp', N'Chương 1: Thương hiệu là gì', N'Bài 1: Từ chiến lược thương hiệu đến hình ảnh', 'https://images.unsplash.com/photo-1611532736597-de2d4265fba3?w=800&auto=format&fit=crop&q=80'),
('K13-DM02-06', 'DM02', 6, 'T2', N'Typography và màu sắc trong thiết kế', N'Cơ bản', 490000, 350000, N'Chọn và phối font chữ, xây bảng màu hài hòa và đảm bảo độ tương phản dễ đọc.', N'Khóa học tập trung vào hai yếu tố quyết định chất lượng một thiết kế: chữ và màu. Bạn học phân loại font, cỡ chữ, khoảng cách dòng, phân cấp thông tin, lý thuyết màu, cách xây bảng màu và kiểm tra độ tương phản theo tiêu chuẩn WCAG.', N'Phối font chữ có phân cấp rõ ràng; Xây bảng màu hài hòa cho sản phẩm; Kiểm tra độ tương phản theo WCAG; Tránh các lỗi trình bày chữ phổ biến', N'Chương 1: Typography cơ bản', N'Bài 1: Phân loại font chữ và cách chọn font', 'https://images.unsplash.com/photo-1513542789411-b6a5d4f31634?w=800&auto=format&fit=crop&q=80'),
('K13-DM02-07', 'DM02', 7, 'T2', N'Prototype tương tác và micro-interaction', N'Trung cấp', 890000, 590000, N'Tạo prototype có chuyển cảnh và hiệu ứng nhỏ để kiểm thử trải nghiệm trước khi lập trình.', N'Bạn học cách dùng Smart Animate, interactive component và biến trong Figma để làm prototype gần với sản phẩm thật, thiết kế micro-interaction cho nút bấm, ô nhập và thông báo, sau đó tổ chức buổi kiểm thử khả dụng với người dùng.', N'Dựng prototype nhiều màn hình trong Figma; Thiết kế micro-interaction có mục đích; Dùng biến để mô phỏng logic đơn giản; Kiểm thử khả dụng với prototype', N'Chương 1: Prototype trong Figma', N'Bài 1: Kết nối màn hình và chuyển cảnh', 'https://images.unsplash.com/photo-1545235617-9465d2a55698?w=800&auto=format&fit=crop&q=80'),
('K13-DM02-08', 'DM02', 8, 'T2', N'Canva cho người không chuyên thiết kế', N'Cơ bản', 299000, 199000, N'Tự làm bài đăng mạng xã hội, slide và ấn phẩm đẹp bằng Canva trong vài phút.', N'Khóa học dành cho nhân viên văn phòng, chủ shop và người làm nội dung chưa học thiết kế. Bạn học bố cục cơ bản, cách chọn màu và chữ, dùng mẫu có sẵn, Brand Kit, làm bài đăng mạng xã hội, slide thuyết trình và video ngắn bằng Canva.', N'Bố cục ấn phẩm rõ ràng và cân đối; Dùng mẫu và Brand Kit của Canva; Làm bài đăng mạng xã hội đồng bộ; Thiết kế slide thuyết trình đẹp', N'Chương 1: Làm quen Canva', N'Bài 1: Giao diện Canva và cách dùng mẫu có sẵn', 'https://images.unsplash.com/photo-1580894894513-541e068a3e2b?w=800&auto=format&fit=crop&q=80'),
('K13-DM02-09', 'DM02', 9, 'T2', N'Thiết kế 3D cơ bản với Blender', N'Trung cấp', 990000, NULL, N'Dựng mô hình, gán vật liệu, ánh sáng và render hình ảnh 3D bằng phần mềm miễn phí Blender.', N'Khóa học hướng dẫn thao tác trong Blender, dựng mô hình đa giác, modifier, UV, vật liệu, ánh sáng, camera và render bằng Cycles hoặc Eevee. Bài thực hành cuối là một cảnh 3D sản phẩm dùng cho quảng cáo.', N'Dựng mô hình 3D bằng đa giác; Gán vật liệu và ánh sáng cho cảnh; Render hình ảnh bằng Cycles và Eevee; Dựng cảnh 3D cho ảnh quảng cáo sản phẩm', N'Chương 1: Làm quen Blender', N'Bài 1: Giao diện và điều hướng trong Blender', 'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=800&auto=format&fit=crop&q=80'),
('K13-DM02-10', 'DM02', 10, 'T2', N'Làm portfolio UI/UX để ứng tuyển', N'Trung cấp', 690000, 490000, N'Chọn dự án, viết case study và trình bày portfolio UI/UX thuyết phục nhà tuyển dụng.', N'Khóa học giúp bạn chọn dự án phù hợp, viết case study theo cấu trúc vấn đề, quá trình, giải pháp và kết quả, trình bày portfolio trên Behance hoặc website cá nhân, đồng thời chuẩn bị cho buổi phỏng vấn và bài test thiết kế.', N'Chọn dự án thể hiện đúng năng lực; Viết case study có cấu trúc rõ ràng; Trình bày portfolio trực tuyến; Chuẩn bị cho phỏng vấn và bài test thiết kế', N'Chương 1: Chuẩn bị portfolio', N'Bài 1: Nhà tuyển dụng tìm gì trong một portfolio', 'https://images.unsplash.com/photo-1559028012-481c04fa702d?w=800&auto=format&fit=crop&q=80'),
('K13-DM03-01', 'DM03', 1, 'T3', N'Thống kê ứng dụng cho phân tích dữ liệu', N'Cơ bản', 690000, 490000, N'Thống kê mô tả, xác suất, kiểm định giả thuyết và hồi quy áp dụng trực tiếp vào dữ liệu thật.', N'Khóa học trình bày thống kê theo hướng ứng dụng, không nặng công thức: trung bình, phương sai, phân phối, khoảng tin cậy, kiểm định giả thuyết, A/B test và hồi quy tuyến tính. Mọi ví dụ đều được tính lại bằng Python để bạn kiểm chứng.', N'Tóm tắt dữ liệu bằng thống kê mô tả; Hiểu phân phối và khoảng tin cậy; Thực hiện kiểm định giả thuyết và A/B test; Diễn giải kết quả hồi quy tuyến tính', N'Chương 1: Thống kê mô tả', N'Bài 1: Trung bình, trung vị và độ phân tán', 'https://images.unsplash.com/photo-1543286386-713bdd548da4?w=800&auto=format&fit=crop&q=80'),
('K13-DM03-02', 'DM03', 2, 'T3', N'SQL cho phân tích dữ liệu', N'Cơ bản', 590000, NULL, N'Truy vấn, tổng hợp và làm sạch dữ liệu bằng SQL để trả lời các câu hỏi kinh doanh.', N'Khóa học dành cho người làm phân tích: viết truy vấn chọn và lọc dữ liệu, JOIN nhiều bảng, GROUP BY, subquery, CTE và window function. Mỗi chương là một bộ câu hỏi kinh doanh thực tế trên cơ sở dữ liệu bán hàng mẫu.', N'Lọc và tổng hợp dữ liệu bằng SQL; Kết hợp nhiều bảng bằng JOIN; Dùng CTE và window function; Trả lời câu hỏi kinh doanh bằng truy vấn', N'Chương 1: Truy vấn cơ bản', N'Bài 1: Cơ sở dữ liệu quan hệ và câu lệnh SELECT', 'https://images.unsplash.com/photo-1504639725590-34d0984388bd?w=800&auto=format&fit=crop&q=80'),
('K13-DM03-03', 'DM03', 3, 'T3', N'Power BI: trực quan hóa và báo cáo', N'Cơ bản', 790000, 590000, N'Kết nối dữ liệu, xây mô hình, viết DAX và thiết kế dashboard tương tác trong Power BI.', N'Bạn học quy trình làm báo cáo trong Power BI: lấy dữ liệu từ Excel và SQL Server, làm sạch bằng Power Query, xây mô hình dữ liệu dạng sao, viết các hàm DAX thông dụng và thiết kế dashboard tương tác để chia sẻ cho quản lý.', N'Làm sạch dữ liệu bằng Power Query; Xây mô hình dữ liệu dạng sao; Viết các phép đo bằng DAX; Thiết kế dashboard tương tác', N'Chương 1: Làm quen Power BI', N'Bài 1: Kết nối nguồn dữ liệu đầu tiên', 'https://images.unsplash.com/photo-1504868584819-f8e8b4b6d7e3?w=800&auto=format&fit=crop&q=80'),
('K13-DM03-04', 'DM03', 4, 'T3', N'Deep Learning với TensorFlow và Keras', N'Nâng cao', 1690000, 1190000, N'Xây dựng và huấn luyện mạng nơ-ron cho bài toán ảnh và chuỗi với TensorFlow, Keras.', N'Khóa học giải thích mạng nơ-ron từ perceptron đến lan truyền ngược, sau đó thực hành với Keras: mạng kết nối đầy đủ, CNN cho phân loại ảnh, RNN và LSTM cho dữ liệu chuỗi, kỹ thuật chống overfitting và học chuyển giao.', N'Hiểu cách mạng nơ-ron học từ dữ liệu; Xây dựng CNN phân loại ảnh; Dùng LSTM cho dữ liệu chuỗi; Áp dụng học chuyển giao với mô hình có sẵn', N'Chương 1: Nền tảng mạng nơ-ron', N'Bài 1: Perceptron và hàm kích hoạt', 'https://images.unsplash.com/photo-1677442136019-21780ecad995?w=800&auto=format&fit=crop&q=80'),
('K13-DM03-05', 'DM03', 5, 'T3', N'Xử lý ngôn ngữ tự nhiên với Python', N'Nâng cao', 1490000, NULL, N'Tiền xử lý văn bản tiếng Việt, biểu diễn từ và xây dựng mô hình phân loại văn bản.', N'Bạn học các bước tiền xử lý văn bản, tách từ tiếng Việt, biểu diễn văn bản bằng TF-IDF và word embedding, phân loại cảm xúc bình luận, trích xuất thực thể và giới thiệu mô hình Transformer. Dữ liệu thực hành là bình luận sản phẩm thương mại điện tử.', N'Tiền xử lý và tách từ tiếng Việt; Biểu diễn văn bản bằng TF-IDF và embedding; Phân loại cảm xúc bình luận; Hiểu kiến trúc Transformer ở mức ứng dụng', N'Chương 1: Tiền xử lý văn bản', N'Bài 1: Bài toán xử lý ngôn ngữ tự nhiên', 'https://images.unsplash.com/photo-1527474305487-b87b222841cc?w=800&auto=format&fit=crop&q=80'),
('K13-DM03-06', 'DM03', 6, 'T3', N'Thị giác máy tính với OpenCV', N'Nâng cao', 1390000, 990000, N'Xử lý ảnh, phát hiện đối tượng và nhận dạng khuôn mặt bằng OpenCV và Python.', N'Khóa học bắt đầu với các phép xử lý ảnh cơ bản như lọc nhiễu, phát hiện biên, tách ngưỡng, sau đó chuyển sang phát hiện đối tượng, theo dõi chuyển động qua camera và nhận dạng khuôn mặt bằng mô hình học sâu có sẵn.', N'Đọc và biến đổi ảnh bằng OpenCV; Phát hiện biên và tách đối tượng; Xử lý video thời gian thực từ camera; Nhận dạng khuôn mặt bằng mô hình có sẵn', N'Chương 1: Xử lý ảnh cơ bản', N'Bài 1: Ảnh số được biểu diễn như thế nào', 'https://images.unsplash.com/photo-1535378917042-10a22c95931a?w=800&auto=format&fit=crop&q=80'),
('K13-DM03-07', 'DM03', 7, 'T3', N'Ứng dụng ChatGPT và Prompt Engineering', N'Cơ bản', 390000, 290000, N'Viết prompt hiệu quả để dùng AI tạo sinh trong học tập, công việc và lập trình.', N'Khóa học giải thích cách mô hình ngôn ngữ lớn hoạt động ở mức trực quan, các nguyên tắc viết prompt rõ ràng, kỹ thuật cho ví dụ mẫu, chia nhỏ nhiệm vụ, yêu cầu định dạng đầu ra và cách kiểm chứng câu trả lời để tránh thông tin sai.', N'Hiểu giới hạn của mô hình ngôn ngữ lớn; Viết prompt rõ ràng có ngữ cảnh; Dùng ví dụ mẫu và chia nhỏ nhiệm vụ; Kiểm chứng câu trả lời của AI', N'Chương 1: AI tạo sinh là gì', N'Bài 1: Mô hình ngôn ngữ lớn hoạt động ra sao', 'https://images.unsplash.com/photo-1620712943543-bcc4688e7485?w=800&auto=format&fit=crop&q=80'),
('K13-DM03-08', 'DM03', 8, 'T3', N'Xây dựng hệ thống gợi ý', N'Nâng cao', 1490000, NULL, N'Lọc cộng tác, gợi ý theo nội dung và đánh giá hệ thống gợi ý như các sàn thương mại điện tử.', N'Khóa học trình bày các phương pháp gợi ý phổ biến: gợi ý theo độ phổ biến, lọc theo nội dung, lọc cộng tác dựa trên người dùng và dựa trên sản phẩm với độ tương đồng cosine, phân rã ma trận, xử lý cold-start và các chỉ số đánh giá như Precision@K.', N'Xây dựng gợi ý theo nội dung; Cài đặt lọc cộng tác dựa trên sản phẩm; Xử lý vấn đề cold-start; Đánh giá hệ thống bằng Precision@K', N'Chương 1: Bài toán gợi ý', N'Bài 1: Hệ thống gợi ý xuất hiện ở đâu quanh ta', 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?w=800&auto=format&fit=crop&q=80'),
('K13-DM03-09', 'DM03', 9, 'T3', N'Data Engineering cơ bản: ETL và Data Warehouse', N'Trung cấp', 1290000, 890000, N'Thiết kế luồng ETL, mô hình kho dữ liệu và lập lịch xử lý dữ liệu tự động.', N'Bạn học vai trò của kỹ sư dữ liệu, thiết kế kho dữ liệu theo mô hình sao, viết luồng trích xuất, biến đổi và nạp dữ liệu bằng Python và SQL, lập lịch chạy bằng Apache Airflow và kiểm tra chất lượng dữ liệu sau mỗi lần nạp.', N'Thiết kế kho dữ liệu theo mô hình sao; Viết luồng ETL bằng Python và SQL; Lập lịch xử lý với Apache Airflow; Kiểm tra chất lượng dữ liệu', N'Chương 1: Vai trò kỹ sư dữ liệu', N'Bài 1: Từ dữ liệu thô đến kho dữ liệu', 'https://images.unsplash.com/photo-1573164713988-8665fc963095?w=800&auto=format&fit=crop&q=80'),
('K13-DM03-10', 'DM03', 10, 'T3', N'Phân tích chuỗi thời gian và dự báo', N'Nâng cao', 1190000, NULL, N'Phân tích xu hướng, mùa vụ và dự báo doanh số bằng ARIMA và Prophet trong Python.', N'Khóa học hướng dẫn phân rã chuỗi thời gian thành xu hướng, mùa vụ và nhiễu, kiểm tra tính dừng, xây dựng mô hình ARIMA, dùng thư viện Prophet và đánh giá sai số dự báo. Dữ liệu thực hành là doanh số bán hàng theo ngày.', N'Phân rã xu hướng và mùa vụ; Kiểm tra tính dừng của chuỗi; Dự báo bằng ARIMA và Prophet; Đánh giá sai số của mô hình dự báo', N'Chương 1: Chuỗi thời gian', N'Bài 1: Đặc điểm của dữ liệu theo thời gian', 'https://images.unsplash.com/photo-1518186285589-2f7649de83e0?w=800&auto=format&fit=crop&q=80'),
('K13-DM04-01', 'DM04', 1, 'T3', N'Kỹ năng bán hàng chuyên nghiệp', N'Cơ bản', 590000, 390000, N'Quy trình bán hàng từ tìm khách, khai thác nhu cầu đến xử lý từ chối và chốt đơn.', N'Khóa học trình bày quy trình bán hàng tư vấn: chuẩn bị, tiếp cận, đặt câu hỏi khai thác nhu cầu, trình bày giải pháp theo lợi ích, xử lý lời từ chối, chốt đơn và chăm sóc sau bán. Mỗi bước có tình huống đóng vai để luyện tập.', N'Đặt câu hỏi khai thác nhu cầu khách hàng; Trình bày sản phẩm theo lợi ích; Xử lý lời từ chối phổ biến; Chốt đơn và chăm sóc sau bán', N'Chương 1: Tư duy bán hàng', N'Bài 1: Bán hàng tư vấn khác bán hàng truyền thống', 'https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?w=800&auto=format&fit=crop&q=80'),
('K13-DM04-02', 'DM04', 2, 'T3', N'Khởi nghiệp tinh gọn (Lean Startup)', N'Trung cấp', 890000, NULL, N'Kiểm chứng ý tưởng kinh doanh nhanh với MVP, vòng lặp xây dựng, đo lường và học hỏi.', N'Khóa học giúp người khởi nghiệp tránh xây sản phẩm không ai cần: viết giả thuyết kinh doanh, dùng Lean Canvas, phỏng vấn khách hàng, xây MVP, đo lường bằng chỉ số có ý nghĩa và quyết định tiếp tục hay chuyển hướng.', N'Viết giả thuyết kinh doanh rõ ràng; Lập Lean Canvas cho ý tưởng; Xây dựng và thử nghiệm MVP; Ra quyết định dựa trên chỉ số', N'Chương 1: Tư duy tinh gọn', N'Bài 1: Vì sao phần lớn startup thất bại', 'https://images.unsplash.com/photo-1512314889357-e157c22f938d?w=800&auto=format&fit=crop&q=80'),
('K13-DM04-03', 'DM04', 3, 'T3', N'Bán hàng trên Shopee và TikTok Shop', N'Cơ bản', 690000, 490000, N'Mở gian hàng, tối ưu sản phẩm, chạy khuyến mãi và livestream bán hàng trên sàn.', N'Bạn học cách đăng ký gian hàng, viết tên và mô tả sản phẩm chuẩn tìm kiếm của sàn, chụp ảnh sản phẩm, định giá, tham gia chương trình khuyến mãi, chạy quảng cáo trong sàn, livestream và theo dõi các chỉ số vận hành gian hàng.', N'Mở và thiết lập gian hàng trên sàn; Tối ưu tên và mô tả sản phẩm; Tham gia khuyến mãi và quảng cáo sàn; Theo dõi chỉ số vận hành gian hàng', N'Chương 1: Chuẩn bị gian hàng', N'Bài 1: Chọn sàn và đăng ký gian hàng', 'https://images.unsplash.com/photo-1563013544-824ae1b704d3?w=800&auto=format&fit=crop&q=80'),
('K13-DM04-04', 'DM04', 4, 'T3', N'Quản lý dự án với Agile và Scrum', N'Trung cấp', 990000, 690000, N'Vận hành dự án theo Scrum: sprint, backlog, các buổi họp và vai trò trong nhóm.', N'Khóa học giải thích tư duy Agile và khung làm việc Scrum: vai trò Product Owner, Scrum Master và nhóm phát triển, quản lý product backlog, ước lượng, lập kế hoạch sprint, họp daily, review, retrospective và dùng bảng Kanban.', N'Hiểu giá trị và nguyên tắc Agile; Vận hành một sprint Scrum trọn vẹn; Viết và sắp xếp product backlog; Theo dõi tiến độ bằng bảng Kanban', N'Chương 1: Tư duy Agile', N'Bài 1: Từ mô hình thác nước đến Agile', 'https://images.unsplash.com/photo-1531403009284-440f080d1e12?w=800&auto=format&fit=crop&q=80'),
('K13-DM04-05', 'DM04', 5, 'T3', N'Kỹ năng thuyết trình và đàm phán', N'Cơ bản', 590000, NULL, N'Chuẩn bị bài nói thuyết phục, làm chủ sân khấu và đàm phán để đạt kết quả đôi bên cùng có lợi.', N'Khóa học gồm hai phần. Phần thuyết trình hướng dẫn xây dựng thông điệp, cấu trúc bài nói, thiết kế slide hỗ trợ, giọng nói và ngôn ngữ cơ thể. Phần đàm phán trình bày cách chuẩn bị, xác định BATNA, nhượng bộ có điều kiện và chốt thỏa thuận.', N'Xây dựng cấu trúc bài thuyết trình; Kiểm soát giọng nói và ngôn ngữ cơ thể; Chuẩn bị đàm phán với BATNA; Đạt thỏa thuận đôi bên cùng có lợi', N'Chương 1: Thuyết trình', N'Bài 1: Xác định thông điệp chính của bài nói', 'https://images.unsplash.com/photo-1556761175-5973dc0f32e7?w=800&auto=format&fit=crop&q=80'),
('K13-DM04-06', 'DM04', 6, 'T3', N'Chăm sóc khách hàng và quản trị CRM', N'Cơ bản', 490000, 350000, N'Xây quy trình chăm sóc khách hàng, xử lý khiếu nại và quản lý dữ liệu khách bằng CRM.', N'Bạn học cách thiết kế hành trình chăm sóc khách hàng, kịch bản trả lời qua điện thoại và tin nhắn, xử lý khiếu nại, đo mức độ hài lòng bằng CSAT và NPS, đồng thời dùng phần mềm CRM để lưu lịch sử và phân nhóm khách hàng.', N'Thiết kế quy trình chăm sóc khách hàng; Xử lý khiếu nại bình tĩnh và hiệu quả; Đo mức hài lòng bằng CSAT và NPS; Quản lý dữ liệu khách hàng trên CRM', N'Chương 1: Trải nghiệm khách hàng', N'Bài 1: Vì sao giữ chân khách hàng quan trọng', 'https://images.unsplash.com/photo-1551836022-d5d88e9218df?w=800&auto=format&fit=crop&q=80'),
('K13-DM04-07', 'DM04', 7, 'T3', N'Excel cơ bản cho dân văn phòng', N'Cơ bản', 390000, 290000, N'Nhập liệu, định dạng, các hàm thông dụng và biểu đồ để xử lý công việc văn phòng hằng ngày.', N'Khóa học dành cho người mới dùng Excel: nhập liệu nhanh, định dạng bảng, sắp xếp và lọc dữ liệu, các hàm SUM, IF, COUNTIF, VLOOKUP, định dạng có điều kiện, vẽ biểu đồ và in ấn. Sau khóa này bạn có thể học tiếp Excel nâng cao.', N'Nhập liệu và định dạng bảng tính; Dùng các hàm tính toán thông dụng; Sắp xếp lọc và định dạng có điều kiện; Vẽ biểu đồ và in báo cáo', N'Chương 1: Làm quen Excel', N'Bài 1: Giao diện Excel và cách nhập liệu nhanh', 'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?w=800&auto=format&fit=crop&q=80'),
('K13-DM04-08', 'DM04', 8, 'T3', N'Quản trị nhân sự cơ bản', N'Cơ bản', 690000, NULL, N'Tuyển dụng, đào tạo, đánh giá hiệu suất và xây dựng chính sách lương thưởng cho doanh nghiệp nhỏ.', N'Khóa học bao quát các nghiệp vụ nhân sự cốt lõi: hoạch định nhân lực, viết mô tả công việc, tuyển dụng và phỏng vấn, hội nhập nhân viên mới, đánh giá hiệu suất theo KPI, chính sách lương thưởng và các quy định cơ bản của Bộ luật Lao động.', N'Viết mô tả công việc và tin tuyển dụng; Phỏng vấn theo năng lực; Đánh giá hiệu suất bằng KPI; Nắm quy định lao động cơ bản', N'Chương 1: Vai trò nhân sự', N'Bài 1: Các mảng công việc của bộ phận nhân sự', 'https://images.unsplash.com/photo-1600880292203-757bb62b4baf?w=800&auto=format&fit=crop&q=80'),
('K13-DM04-09', 'DM04', 9, 'T3', N'Lập kế hoạch kinh doanh', N'Trung cấp', 790000, 590000, N'Viết business plan hoàn chỉnh: phân tích thị trường, mô hình doanh thu và dự báo tài chính.', N'Bạn học cấu trúc một bản kế hoạch kinh doanh: tóm tắt, phân tích thị trường và đối thủ, chân dung khách hàng, chiến lược marketing và bán hàng, kế hoạch vận hành, dự báo doanh thu, chi phí, điểm hòa vốn và cách trình bày với nhà đầu tư.', N'Phân tích thị trường và đối thủ; Xây dựng mô hình doanh thu; Dự báo tài chính và điểm hòa vốn; Trình bày kế hoạch với nhà đầu tư', N'Chương 1: Cấu trúc kế hoạch', N'Bài 1: Một bản kế hoạch kinh doanh gồm những phần nào', 'https://images.unsplash.com/photo-1586281380349-632531db7ed4?w=800&auto=format&fit=crop&q=80'),
('K13-DM04-10', 'DM04', 10, 'T3', N'Quản lý thời gian và năng suất làm việc', N'Cơ bản', 290000, 199000, N'Lập kế hoạch tuần, ưu tiên việc quan trọng và tập trung sâu để làm ít giờ hơn nhưng hiệu quả hơn.', N'Khóa học giới thiệu các phương pháp quản lý thời gian đã được kiểm chứng: ma trận Eisenhower, Pomodoro, time blocking, nguyên tắc 80/20, cách xử lý email và cuộc họp, chống trì hoãn và xây thói quen làm việc tập trung.', N'Ưu tiên việc bằng ma trận Eisenhower; Lập kế hoạch tuần bằng time blocking; Tập trung sâu với Pomodoro; Giảm trì hoãn và gián đoạn', N'Chương 1: Hiểu thời gian của bạn', N'Bài 1: Ghi nhận thời gian đang dùng vào đâu', 'https://images.unsplash.com/photo-1499750310107-5fef28a66643?w=800&auto=format&fit=crop&q=80'),
('K13-DM06-01', 'DM06', 1, 'T2', N'Nhiếp ảnh cơ bản: khẩu độ, tốc độ, ISO', N'Cơ bản', 590000, 390000, N'Làm chủ tam giác phơi sáng, lấy nét và bố cục để chụp ảnh ở chế độ thủ công.', N'Khóa học giúp người mới chuyển từ chế độ tự động sang chụp thủ công: hiểu khẩu độ, tốc độ màn trập, ISO và cách chúng ảnh hưởng đến ảnh, chế độ đo sáng, lấy nét, cân bằng trắng và các quy tắc bố cục cơ bản.', N'Cân bằng khẩu độ tốc độ và ISO; Chụp ở chế độ thủ công; Lấy nét và đo sáng chính xác; Áp dụng quy tắc bố cục cơ bản', N'Chương 1: Làm quen máy ảnh', N'Bài 1: Các bộ phận và chế độ chụp của máy ảnh', 'https://images.unsplash.com/photo-1502920917128-1aa500764cbd?w=800&auto=format&fit=crop&q=80'),
('K13-DM06-02', 'DM06', 2, 'T2', N'Chụp ảnh chân dung với ánh sáng tự nhiên', N'Trung cấp', 790000, NULL, N'Tìm ánh sáng đẹp, hướng dẫn tạo dáng và chụp chân dung có chiều sâu ngoài trời.', N'Bạn học đọc hướng và chất lượng ánh sáng tự nhiên, chụp giờ vàng, dùng tấm hắt sáng, chọn tiêu cự và khẩu độ để xóa phông, giao tiếp và hướng dẫn người mẫu tạo dáng tự nhiên, sau đó chọn ảnh và hậu kỳ màu da.', N'Đọc hướng và chất lượng ánh sáng; Chọn ống kính và khẩu độ cho chân dung; Hướng dẫn người mẫu tạo dáng; Chỉnh màu da tự nhiên', N'Chương 1: Ánh sáng cho chân dung', N'Bài 1: Ánh sáng thuận ngược và xiên', 'https://images.unsplash.com/photo-1542038784456-1ea8e935640e?w=800&auto=format&fit=crop&q=80'),
('K13-DM06-03', 'DM06', 3, 'T2', N'Hậu kỳ ảnh với Lightroom Classic', N'Cơ bản', 690000, 490000, N'Quản lý thư viện ảnh và chỉnh màu chuyên nghiệp, đồng bộ cả bộ ảnh trong Lightroom.', N'Khóa học hướng dẫn nhập và tổ chức thư viện ảnh, chỉnh phơi sáng, cân bằng trắng, đường cong, màu HSL, mặt nạ cục bộ, tạo preset để đồng bộ màu cho cả bộ ảnh và xuất ảnh đúng kích thước cho mạng xã hội hoặc in ấn.', N'Tổ chức thư viện ảnh khoa học; Chỉnh phơi sáng và màu sắc; Dùng mặt nạ để chỉnh cục bộ; Tạo preset đồng bộ màu cho bộ ảnh', N'Chương 1: Làm quen Lightroom', N'Bài 1: Nhập ảnh và tổ chức thư viện', 'https://images.unsplash.com/photo-1468495244123-6c6c332eeece?w=800&auto=format&fit=crop&q=80'),
('K13-DM06-04', 'DM06', 4, 'T2', N'Dựng video với Adobe Premiere Pro', N'Cơ bản', 890000, 590000, N'Cắt dựng, chèn chữ, xử lý âm thanh và xuất video hoàn chỉnh bằng Premiere Pro.', N'Bạn học quy trình dựng video: tạo dự án, quản lý tư liệu, cắt ghép trên timeline, chuyển cảnh, chèn chữ và đồ họa, xử lý âm thanh, chỉnh màu cơ bản và xuất video với thông số phù hợp cho YouTube và mạng xã hội.', N'Cắt ghép video trên timeline; Chèn chữ và chuyển cảnh hợp lý; Xử lý âm thanh rõ ràng; Xuất video đúng thông số từng nền tảng', N'Chương 1: Làm quen Premiere Pro', N'Bài 1: Tạo dự án và quản lý tư liệu', 'https://images.unsplash.com/photo-1574717024653-61fd2cf4d44d?w=800&auto=format&fit=crop&q=80'),
('K13-DM06-05', 'DM06', 5, 'T2', N'Quay và dựng video ngắn bằng điện thoại', N'Cơ bản', 390000, 290000, N'Quay video dọc đẹp bằng điện thoại và dựng nhanh bằng CapCut cho TikTok, Reels.', N'Khóa học hướng dẫn thiết lập điện thoại khi quay, giữ máy ổn định, tận dụng ánh sáng, thu âm rõ, lên kịch bản video ngắn có móc câu ở ba giây đầu và dựng bằng CapCut với phụ đề, nhạc nền, hiệu ứng chuyển cảnh.', N'Thiết lập điện thoại để quay video đẹp; Lên kịch bản video ngắn thu hút; Dựng video bằng CapCut; Thêm phụ đề và nhạc nền đúng cách', N'Chương 1: Quay bằng điện thoại', N'Bài 1: Cài đặt camera điện thoại trước khi quay', 'https://images.unsplash.com/photo-1512941937669-90a1b58e7e9c?w=800&auto=format&fit=crop&q=80'),
('K13-DM06-06', 'DM06', 6, 'T2', N'Chỉnh màu video với DaVinci Resolve', N'Nâng cao', 1090000, NULL, N'Chỉnh màu kỹ thuật và tạo màu điện ảnh bằng node trong DaVinci Resolve.', N'Khóa học dành cho người đã biết dựng video: đọc biểu đồ waveform và vectorscope, cân màu kỹ thuật, làm việc với node, chỉnh màu da, khớp màu giữa các cảnh quay, dùng LUT và tạo phong cách màu điện ảnh.', N'Đọc waveform và vectorscope; Cân màu kỹ thuật cho cảnh quay; Khớp màu giữa nhiều cảnh; Tạo phong cách màu điện ảnh', N'Chương 1: Nền tảng chỉnh màu', N'Bài 1: Chỉnh màu kỹ thuật và chỉnh màu sáng tạo', 'https://images.unsplash.com/photo-1547082299-de196ea013d6?w=800&auto=format&fit=crop&q=80'),
('K13-DM06-07', 'DM06', 7, 'T2', N'Nhiếp ảnh phong cảnh', N'Trung cấp', 690000, 490000, N'Lên kế hoạch chuyến chụp, dùng kính lọc và phơi sáng dài để có ảnh phong cảnh ấn tượng.', N'Bạn học cách chọn địa điểm và thời điểm chụp, đọc dự báo thời tiết, bố cục phong cảnh với tiền cảnh, dùng chân máy, kính lọc ND và CPL, phơi sáng dài, ghép dải sáng HDR và hậu kỳ ảnh phong cảnh.', N'Lên kế hoạch thời điểm và địa điểm chụp; Bố cục phong cảnh có chiều sâu; Dùng kính lọc và phơi sáng dài; Ghép HDR và hậu kỳ phong cảnh', N'Chương 1: Chuẩn bị chuyến chụp', N'Bài 1: Chọn thời điểm có ánh sáng đẹp', 'https://images.unsplash.com/photo-1492691527719-9d1e07e534b4?w=800&auto=format&fit=crop&q=80'),
('K13-DM06-08', 'DM06', 8, 'T2', N'Quay flycam cơ bản', N'Trung cấp', 990000, 790000, N'Điều khiển drone an toàn, quay các chuyển động máy đẹp và nắm quy định bay tại Việt Nam.', N'Khóa học hướng dẫn kiểm tra thiết bị trước khi bay, điều khiển drone trong các tình huống cơ bản, các chuyển động máy thường dùng khi quay, thiết lập camera trên drone, xử lý sự cố và những quy định cần biết về khu vực cấm bay.', N'Kiểm tra thiết bị trước mỗi lần bay; Điều khiển drone an toàn; Quay các chuyển động máy cơ bản; Nắm quy định về khu vực bay', N'Chương 1: An toàn bay', N'Bài 1: Kiểm tra drone trước khi cất cánh', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=800&auto=format&fit=crop&q=80'),
('K13-DM06-09', 'DM06', 9, 'T2', N'Làm YouTube: kịch bản, quay và dựng', N'Cơ bản', 590000, NULL, N'Xây kênh YouTube từ chọn chủ đề, viết kịch bản, quay dựng đến tối ưu tiêu đề và thumbnail.', N'Khóa học đi qua toàn bộ quy trình sản xuất nội dung YouTube: chọn ngách, lên lịch đăng, viết kịch bản giữ chân người xem, bố trí ánh sáng và âm thanh tại nhà, dựng video, thiết kế thumbnail và đọc số liệu YouTube Studio.', N'Chọn chủ đề và định vị kênh; Viết kịch bản giữ chân người xem; Quay và dựng video tại nhà; Tối ưu tiêu đề và thumbnail', N'Chương 1: Định hướng kênh', N'Bài 1: Chọn chủ đề phù hợp với bạn', 'https://images.unsplash.com/photo-1554048612-b6a482bc67e5?w=800&auto=format&fit=crop&q=80'),
('K13-DM06-10', 'DM06', 10, 'T2', N'Chụp ảnh sự kiện và cưới', N'Nâng cao', 1190000, 890000, N'Chụp sự kiện và tiệc cưới: chuẩn bị thiết bị, đón khoảnh khắc và xử lý ánh sáng khó.', N'Bạn học cách làm việc với khách hàng trước sự kiện, chuẩn bị danh sách cảnh cần chụp, thiết bị dự phòng, chụp trong điều kiện thiếu sáng, dùng đèn flash gắn máy, đón khoảnh khắc tự nhiên và giao ảnh đúng hạn.', N'Lên danh sách cảnh cần chụp với khách hàng; Chụp trong điều kiện thiếu sáng; Dùng đèn flash gắn máy hợp lý; Đón khoảnh khắc tự nhiên', N'Chương 1: Chuẩn bị sự kiện', N'Bài 1: Làm việc với khách hàng trước buổi chụp', 'https://images.unsplash.com/photo-1516035069371-29a1b244cc32?w=800&auto=format&fit=crop&q=80'),
('K13-C002-01', 'CAT-002', 1, 'T3', N'Nguyên lý kế toán cho người mới', N'Cơ bản', 590000, 390000, N'Hiểu phương trình kế toán, ghi sổ kép, hệ thống tài khoản và lập báo cáo cơ bản.', N'Khóa học dành cho người chưa học kế toán: tài sản, nguồn vốn, phương trình kế toán, nguyên tắc ghi sổ kép, hệ thống tài khoản theo Thông tư 200 và 133, định khoản các nghiệp vụ thường gặp và lập bảng cân đối số phát sinh.', N'Hiểu phương trình kế toán; Định khoản theo nguyên tắc ghi sổ kép; Sử dụng hệ thống tài khoản kế toán; Lập bảng cân đối số phát sinh', N'Chương 1: Bản chất kế toán', N'Bài 1: Tài sản và nguồn vốn', 'https://images.unsplash.com/photo-1554224155-6726b3ff858f?w=800&auto=format&fit=crop&q=80'),
('K13-C002-02', 'CAT-002', 2, 'T3', N'Đọc hiểu báo cáo tài chính', N'Cơ bản', 690000, NULL, N'Đọc bảng cân đối kế toán, báo cáo kết quả kinh doanh và lưu chuyển tiền tệ của doanh nghiệp.', N'Bạn học cấu trúc và ý nghĩa của ba báo cáo tài chính chính, mối liên hệ giữa chúng, cách đọc thuyết minh và nhận diện các dấu hiệu bất thường. Ví dụ minh họa lấy từ báo cáo tài chính công bố của doanh nghiệp niêm yết.', N'Đọc bảng cân đối kế toán; Phân tích báo cáo kết quả kinh doanh; Hiểu báo cáo lưu chuyển tiền tệ; Nhận diện dấu hiệu bất thường', N'Chương 1: Bộ báo cáo tài chính', N'Bài 1: Ba báo cáo tài chính quan trọng nhất', 'https://images.unsplash.com/photo-1450101499163-c8848c66ca85?w=800&auto=format&fit=crop&q=80'),
('K13-C002-03', 'CAT-002', 3, 'T3', N'Kế toán thuế thực hành', N'Trung cấp', 990000, 690000, N'Kê khai và quyết toán thuế GTGT, TNDN, TNCN cho doanh nghiệp vừa và nhỏ.', N'Khóa học hướng dẫn quy trình thuế của doanh nghiệp vừa và nhỏ: đăng ký thuế, hóa đơn điện tử, kê khai thuế giá trị gia tăng, thuế thu nhập doanh nghiệp, thuế thu nhập cá nhân, quyết toán cuối năm và các lỗi thường gặp khi bị kiểm tra.', N'Lập và quản lý hóa đơn điện tử; Kê khai thuế GTGT theo tháng và quý; Quyết toán thuế TNDN và TNCN; Tránh lỗi thường gặp khi kê khai', N'Chương 1: Tổng quan thuế', N'Bài 1: Các loại thuế doanh nghiệp phải nộp', 'https://images.unsplash.com/photo-1559526324-4b87b5e36e44?w=800&auto=format&fit=crop&q=80'),
('K13-C002-04', 'CAT-002', 4, 'T3', N'Phần mềm kế toán MISA thực hành', N'Cơ bản', 790000, NULL, N'Nhập liệu chứng từ, khóa sổ và lập báo cáo tài chính trên phần mềm kế toán MISA.', N'Bạn thực hành trên dữ liệu của một doanh nghiệp thương mại: khai báo danh mục, nhập số dư đầu kỳ, hạch toán mua bán hàng, tiền lương, tài sản cố định, kết chuyển cuối kỳ, khóa sổ và in báo cáo tài chính trên phần mềm MISA.', N'Khai báo danh mục và số dư đầu kỳ; Hạch toán nghiệp vụ mua bán hàng; Kết chuyển và khóa sổ cuối kỳ; Lập báo cáo tài chính trên phần mềm', N'Chương 1: Khởi tạo dữ liệu', N'Bài 1: Tạo dữ liệu kế toán cho doanh nghiệp', 'https://images.unsplash.com/photo-1593642632559-0c6d3fc62b89?w=800&auto=format&fit=crop&q=80'),
('K13-C002-05', 'CAT-002', 5, 'T3', N'Quản lý tài chính cá nhân', N'Cơ bản', 290000, 199000, N'Lập ngân sách, quản lý nợ, xây quỹ dự phòng và bắt đầu đầu tư cho mục tiêu dài hạn.', N'Khóa học giúp bạn kiểm soát dòng tiền cá nhân: ghi chép chi tiêu, lập ngân sách theo quy tắc 50/30/20, trả nợ thông minh, xây quỹ dự phòng, chọn bảo hiểm phù hợp và hiểu các kênh đầu tư cơ bản trước khi bắt đầu.', N'Ghi chép và phân loại chi tiêu; Lập ngân sách theo quy tắc 50/30/20; Xây quỹ dự phòng khẩn cấp; Hiểu các kênh đầu tư cơ bản', N'Chương 1: Hiểu dòng tiền của bạn', N'Bài 1: Tiền của bạn đang đi đâu', 'https://images.unsplash.com/photo-1633158829585-23ba8f7c8caf?w=800&auto=format&fit=crop&q=80'),
('K13-C002-06', 'CAT-002', 6, 'T3', N'Đầu tư chứng khoán cơ bản', N'Cơ bản', 790000, 590000, N'Hiểu thị trường chứng khoán Việt Nam, mở tài khoản, đặt lệnh và quản trị rủi ro.', N'Khóa học trình bày cách thị trường chứng khoán vận hành, các sàn giao dịch, loại lệnh, phí và thuế, cách đọc bảng giá, phân tích cơ bản doanh nghiệp qua các chỉ số P/E, ROE, phân tích kỹ thuật nhập môn và nguyên tắc quản trị rủi ro.', N'Đặt lệnh và đọc bảng giá chứng khoán; Đánh giá doanh nghiệp qua chỉ số tài chính; Đọc biểu đồ giá cơ bản; Quản trị rủi ro khi đầu tư', N'Chương 1: Thị trường chứng khoán', N'Bài 1: Cổ phiếu là gì và sinh lời ra sao', 'https://images.unsplash.com/photo-1611974789855-9c2a0a7236a3?w=800&auto=format&fit=crop&q=80'),
('K13-C002-07', 'CAT-002', 7, 'T3', N'Phân tích tài chính doanh nghiệp', N'Trung cấp', 1090000, NULL, N'Phân tích khả năng sinh lời, thanh khoản, đòn bẩy và hiệu quả hoạt động qua các chỉ số tài chính.', N'Bạn học phân tích theo chiều ngang, chiều dọc và theo nhóm chỉ số: thanh khoản, đòn bẩy, hiệu quả hoạt động, khả năng sinh lời, mô hình DuPont, so sánh với doanh nghiệp cùng ngành và viết nhận định tài chính ngắn gọn.', N'Tính và diễn giải các nhóm chỉ số tài chính; Phân tích ROE bằng mô hình DuPont; So sánh với doanh nghiệp cùng ngành; Viết nhận định tài chính ngắn gọn', N'Chương 1: Phương pháp phân tích', N'Bài 1: Phân tích ngang và phân tích dọc', 'https://images.unsplash.com/photo-1590283603385-17ffb3a7f29f?w=800&auto=format&fit=crop&q=80'),
('K13-C002-08', 'CAT-002', 8, 'T3', N'Mô hình tài chính với Excel', N'Nâng cao', 1290000, 990000, N'Dựng mô hình ba báo cáo, dự phóng dòng tiền và định giá doanh nghiệp bằng DCF trên Excel.', N'Khóa học hướng dẫn xây dựng mô hình tài chính chuẩn: giả định đầu vào, dự phóng doanh thu và chi phí, liên kết ba báo cáo tài chính, lập bảng dòng tiền tự do, định giá theo phương pháp chiết khấu dòng tiền và phân tích độ nhạy.', N'Tổ chức mô hình tài chính rõ ràng; Liên kết ba báo cáo tài chính; Định giá doanh nghiệp bằng DCF; Phân tích độ nhạy của kết quả', N'Chương 1: Cấu trúc mô hình', N'Bài 1: Nguyên tắc xây dựng mô hình tài chính', 'https://images.unsplash.com/photo-1501504905252-473c47e087f8?w=800&auto=format&fit=crop&q=80'),
('K13-C002-09', 'CAT-002', 9, 'T3', N'Kế toán quản trị và kiểm soát chi phí', N'Trung cấp', 890000, 690000, N'Phân loại chi phí, tính giá thành, phân tích điểm hòa vốn và lập dự toán ngân sách.', N'Bạn học cách kế toán quản trị hỗ trợ ra quyết định: phân loại chi phí cố định và biến đổi, tính giá thành sản phẩm, phân tích chi phí khối lượng lợi nhuận, điểm hòa vốn, lập dự toán và phân tích chênh lệch giữa thực tế với kế hoạch.', N'Phân loại chi phí theo cách ứng xử; Tính giá thành sản phẩm; Phân tích điểm hòa vốn; Lập dự toán và phân tích chênh lệch', N'Chương 1: Vai trò kế toán quản trị', N'Bài 1: Kế toán quản trị khác kế toán tài chính', 'https://images.unsplash.com/photo-1604594849809-dfedbc827105?w=800&auto=format&fit=crop&q=80'),
('K13-C002-10', 'CAT-002', 10, 'T3', N'Lập ngân sách và quản lý dòng tiền doanh nghiệp nhỏ', N'Cơ bản', 590000, NULL, N'Dự báo dòng tiền, quản lý công nợ và tồn kho để doanh nghiệp nhỏ không thiếu tiền mặt.', N'Khóa học dành cho chủ doanh nghiệp nhỏ và hộ kinh doanh: phân biệt lợi nhuận và dòng tiền, lập kế hoạch dòng tiền 13 tuần, quản lý công nợ phải thu, phải trả, kiểm soát tồn kho và chuẩn bị hồ sơ khi cần vay vốn ngân hàng.', N'Phân biệt lợi nhuận và dòng tiền; Lập kế hoạch dòng tiền 13 tuần; Quản lý công nợ và tồn kho; Chuẩn bị hồ sơ vay vốn', N'Chương 1: Dòng tiền là gì', N'Bài 1: Có lãi nhưng vẫn thiếu tiền', 'https://images.unsplash.com/photo-1579621970563-ebec7560ff3e?w=800&auto=format&fit=crop&q=80'),
('K13-C003-01', 'CAT-003', 1, 'T3', N'Facebook Ads từ cơ bản đến tối ưu chuyển đổi', N'Cơ bản', 790000, 490000, N'Thiết lập tài khoản quảng cáo, chọn đối tượng, viết mẫu quảng cáo và tối ưu chi phí trên Meta.', N'Khóa học hướng dẫn cấu trúc chiến dịch, nhóm quảng cáo và quảng cáo trên Meta Ads Manager, chọn mục tiêu, nhắm đối tượng, gắn Meta Pixel, viết mẫu quảng cáo, thử nghiệm A/B và đọc các chỉ số để tối ưu chi phí trên mỗi đơn hàng.', N'Thiết lập chiến dịch đúng mục tiêu; Nhắm đúng đối tượng khách hàng; Gắn Meta Pixel để đo chuyển đổi; Tối ưu chi phí dựa trên chỉ số', N'Chương 1: Nền tảng quảng cáo Meta', N'Bài 1: Cấu trúc một chiến dịch quảng cáo', 'https://images.unsplash.com/photo-1563986768494-4dee2763ff3f?w=800&auto=format&fit=crop&q=80'),
('K13-C003-02', 'CAT-003', 2, 'T3', N'SEO website lên top Google', N'Trung cấp', 990000, 690000, N'Nghiên cứu từ khóa, tối ưu onpage, kỹ thuật và xây liên kết để tăng lượt truy cập tự nhiên.', N'Bạn học cách Google xếp hạng trang, nghiên cứu từ khóa theo ý định tìm kiếm, tối ưu tiêu đề, nội dung, tốc độ và cấu trúc website, sửa lỗi kỹ thuật bằng Google Search Console và xây dựng liên kết một cách an toàn.', N'Nghiên cứu từ khóa theo ý định tìm kiếm; Tối ưu onpage cho từng trang; Sửa lỗi kỹ thuật bằng Search Console; Xây dựng liên kết an toàn', N'Chương 1: Google tìm kiếm thế nào', N'Bài 1: Thu thập lập chỉ mục và xếp hạng', 'https://images.unsplash.com/photo-1557838923-2985c318be48?w=800&auto=format&fit=crop&q=80'),
('K13-C003-03', 'CAT-003', 3, 'T3', N'Content Marketing và viết bài chuẩn SEO', N'Cơ bản', 590000, NULL, N'Lập kế hoạch nội dung, viết bài blog chuẩn SEO và phân phối nội dung đa kênh.', N'Khóa học giúp bạn xây chiến lược nội dung theo chân dung khách hàng và hành trình mua hàng, lên lịch đăng, viết bài blog có cấu trúc rõ ràng và chuẩn SEO, tái sử dụng nội dung cho mạng xã hội và đo hiệu quả từng bài viết.', N'Lập lịch nội dung theo hành trình khách hàng; Viết bài blog có cấu trúc rõ ràng; Tối ưu bài viết cho công cụ tìm kiếm; Đo hiệu quả từng bài viết', N'Chương 1: Chiến lược nội dung', N'Bài 1: Nội dung phục vụ mục tiêu kinh doanh', 'https://images.unsplash.com/photo-1488190211105-8b0e65b80b4e?w=800&auto=format&fit=crop&q=80'),
('K13-C003-04', 'CAT-003', 4, 'T3', N'Google Ads: quảng cáo tìm kiếm', N'Trung cấp', 890000, 590000, N'Chạy quảng cáo tìm kiếm trên Google: chọn từ khóa, viết mẫu quảng cáo và tối ưu điểm chất lượng.', N'Bạn học cách thiết lập tài khoản Google Ads, cấu trúc chiến dịch tìm kiếm, chọn loại đối sánh từ khóa, viết quảng cáo thích ứng, tối ưu trang đích, theo dõi chuyển đổi và điều chỉnh giá thầu để giảm chi phí trên mỗi chuyển đổi.', N'Xây cấu trúc chiến dịch tìm kiếm; Chọn từ khóa và loại đối sánh; Viết quảng cáo tìm kiếm hấp dẫn; Theo dõi chuyển đổi và tối ưu giá thầu', N'Chương 1: Làm quen Google Ads', N'Bài 1: Quảng cáo tìm kiếm hoạt động thế nào', 'https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?w=800&auto=format&fit=crop&q=80'),
('K13-C003-05', 'CAT-003', 5, 'T3', N'TikTok Marketing và xây kênh video ngắn', N'Cơ bản', 690000, NULL, N'Xây kênh TikTok cho thương hiệu, sản xuất video ngắn theo xu hướng và chạy quảng cáo TikTok.', N'Khóa học trình bày cách thuật toán đề xuất của TikTok hoạt động, định vị kênh thương hiệu, lên kế hoạch nội dung theo xu hướng, viết kịch bản video ngắn, hợp tác với nhà sáng tạo nội dung và chạy quảng cáo TikTok Ads.', N'Định vị kênh TikTok cho thương hiệu; Lên kế hoạch nội dung theo xu hướng; Hợp tác với nhà sáng tạo nội dung; Chạy quảng cáo TikTok Ads', N'Chương 1: Hiểu nền tảng TikTok', N'Bài 1: Thuật toán đề xuất của TikTok', 'https://images.unsplash.com/photo-1611162616305-c69b3fa7fbe0?w=800&auto=format&fit=crop&q=80'),
('K13-C003-06', 'CAT-003', 6, 'T3', N'Email Marketing tự động', N'Trung cấp', 590000, 390000, N'Xây danh sách email, thiết kế chuỗi email tự động và tăng tỷ lệ mở, tỷ lệ nhấp.', N'Bạn học cách thu thập email hợp pháp, phân nhóm danh sách, viết tiêu đề và nội dung email, thiết kế chuỗi email chào mừng, bỏ quên giỏ hàng và chăm sóc khách cũ bằng công cụ tự động, cùng các yếu tố giúp email không vào hộp thư rác.', N'Xây và phân nhóm danh sách email; Viết tiêu đề tăng tỷ lệ mở; Thiết kế chuỗi email tự động; Tránh email rơi vào hộp thư rác', N'Chương 1: Nền tảng email marketing', N'Bài 1: Vì sao email vẫn hiệu quả', 'https://images.unsplash.com/photo-1486312338219-ce68d2c6f44d?w=800&auto=format&fit=crop&q=80'),
('K13-C003-07', 'CAT-003', 7, 'T3', N'Xây dựng thương hiệu cá nhân', N'Cơ bản', 490000, 350000, N'Định vị bản thân, chọn kênh và tạo nội dung đều đặn để xây uy tín trong lĩnh vực của bạn.', N'Khóa học giúp bạn xác định điểm mạnh và đối tượng muốn hướng tới, xây thông điệp cá nhân, tối ưu hồ sơ LinkedIn và mạng xã hội, lên kế hoạch nội dung chia sẻ chuyên môn và mở rộng mạng lưới quan hệ một cách tự nhiên.', N'Xác định định vị cá nhân; Tối ưu hồ sơ LinkedIn và mạng xã hội; Tạo nội dung chia sẻ chuyên môn đều đặn; Mở rộng mạng lưới quan hệ', N'Chương 1: Định vị bản thân', N'Bài 1: Bạn muốn được biết đến vì điều gì', 'https://images.unsplash.com/photo-1600267175161-cfaa711b4a81?w=800&auto=format&fit=crop&q=80'),
('K13-C003-08', 'CAT-003', 8, 'T3', N'Google Analytics 4 và đo lường marketing', N'Trung cấp', 790000, NULL, N'Cài đặt GA4, theo dõi sự kiện, chuyển đổi và đọc báo cáo để đánh giá hiệu quả từng kênh.', N'Bạn học mô hình dữ liệu dựa trên sự kiện của GA4, cài đặt qua Google Tag Manager, đánh dấu chuyển đổi, gắn tham số UTM cho chiến dịch, đọc báo cáo thu hút người dùng và phân bổ chuyển đổi để biết kênh nào mang lại doanh thu.', N'Cài đặt GA4 qua Google Tag Manager; Theo dõi sự kiện và chuyển đổi; Gắn tham số UTM cho chiến dịch; Đánh giá hiệu quả từng kênh', N'Chương 1: Làm quen GA4', N'Bài 1: Mô hình dữ liệu dựa trên sự kiện', 'https://images.unsplash.com/photo-1560472354-b33ff0c44a43?w=800&auto=format&fit=crop&q=80'),
('K13-C003-09', 'CAT-003', 9, 'T3', N'Copywriting: viết quảng cáo bán hàng', N'Cơ bản', 490000, NULL, N'Viết tiêu đề, nội dung quảng cáo và trang bán hàng thuyết phục theo các công thức AIDA, PAS.', N'Khóa học giúp bạn hiểu tâm lý khách hàng, chuyển tính năng thành lợi ích, áp dụng các công thức AIDA, PAS, viết tiêu đề thu hút, lời kêu gọi hành động rõ ràng và kiểm tra hiệu quả bằng thử nghiệm A/B.', N'Chuyển tính năng thành lợi ích; Viết theo công thức AIDA và PAS; Viết tiêu đề và lời kêu gọi hành động; Thử nghiệm A/B nội dung quảng cáo', N'Chương 1: Tâm lý khách hàng', N'Bài 1: Khách hàng mua vì điều gì', 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=800&auto=format&fit=crop&q=80'),
('K13-C003-10', 'CAT-003', 10, 'T3', N'Lập kế hoạch Marketing tổng thể', N'Trung cấp', 990000, 690000, N'Phân tích thị trường, chọn chiến lược 4P, phân bổ ngân sách và đo lường kế hoạch marketing.', N'Bạn học quy trình lập kế hoạch marketing: phân tích SWOT, phân khúc và chọn thị trường mục tiêu, định vị, xây chiến lược sản phẩm, giá, phân phối, truyền thông, phân bổ ngân sách theo kênh, đặt KPI và theo dõi kết quả.', N'Phân tích SWOT và thị trường mục tiêu; Xây chiến lược 4P; Phân bổ ngân sách theo kênh; Đặt KPI và theo dõi kết quả', N'Chương 1: Phân tích thị trường', N'Bài 1: Phân khúc và chọn thị trường mục tiêu', 'https://images.unsplash.com/photo-1533750349088-cd871a92f312?w=800&auto=format&fit=crop&q=80'),
('K13-C004-01', 'CAT-004', 1, 'T2', N'AutoCAD 2D cho người mới', N'Cơ bản', 690000, 490000, N'Vẽ và trình bày bản vẽ kỹ thuật 2D bằng AutoCAD: lệnh vẽ, layer, kích thước và in ấn.', N'Khóa học hướng dẫn thiết lập bản vẽ, các lệnh vẽ và hiệu chỉnh, quản lý layer, block, ghi kích thước, chú thích, khung tên và in bản vẽ theo tỉ lệ. Bài thực hành là mặt bằng một căn hộ hoàn chỉnh.', N'Dùng thành thạo các lệnh vẽ và hiệu chỉnh; Quản lý layer và block; Ghi kích thước và chú thích; In bản vẽ đúng tỉ lệ', N'Chương 1: Làm quen AutoCAD', N'Bài 1: Giao diện AutoCAD và thiết lập bản vẽ', 'https://images.unsplash.com/photo-1503387762-592deb58ef4e?w=800&auto=format&fit=crop&q=80'),
('K13-C004-02', 'CAT-004', 2, 'T2', N'SketchUp và V-Ray thiết kế nội thất', N'Trung cấp', 1190000, 890000, N'Dựng mô hình nội thất 3D trong SketchUp và render ảnh chân thực bằng V-Ray.', N'Bạn học dựng mô hình phòng từ bản vẽ mặt bằng, tạo đồ nội thất, dùng component, gán vật liệu, đặt ánh sáng ban ngày và ban đêm, thiết lập camera và render ảnh phối cảnh nội thất chân thực bằng V-Ray.', N'Dựng mô hình phòng từ mặt bằng; Tạo và quản lý đồ nội thất; Gán vật liệu và ánh sáng; Render phối cảnh bằng V-Ray', N'Chương 1: Dựng hình SketchUp', N'Bài 1: Dựng tường cửa và sàn từ mặt bằng', 'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?w=800&auto=format&fit=crop&q=80'),
('K13-C004-03', 'CAT-004', 3, 'T2', N'Nguyên lý thiết kế nội thất nhà ở', N'Cơ bản', 790000, NULL, N'Bố trí công năng, chọn phong cách, phối màu, vật liệu và ánh sáng cho không gian sống.', N'Khóa học trình bày các nguyên lý cơ bản của thiết kế nội thất: công thái học và kích thước chuẩn, bố trí công năng từng phòng, các phong cách phổ biến, phối màu, chọn vật liệu, chiếu sáng và cách trình bày ý tưởng với chủ nhà.', N'Bố trí công năng hợp lý cho từng phòng; Nhận diện các phong cách nội thất; Phối màu và chọn vật liệu; Thiết kế chiếu sáng cho không gian sống', N'Chương 1: Không gian và công năng', N'Bài 1: Công thái học và kích thước chuẩn', 'https://images.unsplash.com/photo-1586023492125-27b2c045efd7?w=800&auto=format&fit=crop&q=80'),
('K13-C004-04', 'CAT-004', 4, 'T2', N'Thiết kế bao bì sản phẩm', N'Trung cấp', 890000, 590000, N'Thiết kế hộp, nhãn và túi bao bì từ ý tưởng, dàn trang đến file in đúng kỹ thuật.', N'Bạn học vai trò của bao bì trong bán hàng, nghiên cứu đối thủ trên kệ, chọn chất liệu, dựng khuôn bế, thiết kế mặt trước và thông tin bắt buộc trên nhãn, làm mockup trình bày và chuẩn bị file in với màu CMYK, tràn lề.', N'Phân tích bao bì của đối thủ; Dựng khuôn bế cho hộp sản phẩm; Trình bày thông tin bắt buộc trên nhãn; Chuẩn bị file in đúng kỹ thuật', N'Chương 1: Bao bì và bán hàng', N'Bài 1: Bao bì tác động đến quyết định mua thế nào', 'https://images.unsplash.com/photo-1607082348824-0a96f2a4b9da?w=800&auto=format&fit=crop&q=80'),
('K13-C004-05', 'CAT-004', 5, 'T2', N'Dàn trang ấn phẩm với Adobe InDesign', N'Cơ bản', 690000, NULL, N'Dàn trang sách, tạp chí, catalogue nhiều trang chuyên nghiệp bằng Adobe InDesign.', N'Khóa học hướng dẫn thiết lập tài liệu nhiều trang, lưới và trang mẫu, kiểu đoạn và kiểu ký tự, xử lý văn bản dài, chèn ảnh, mục lục tự động và xuất file PDF chuẩn in. Bài thực hành là một catalogue sản phẩm mười hai trang.', N'Thiết lập lưới và trang mẫu; Dùng kiểu đoạn và kiểu ký tự; Tạo mục lục tự động; Xuất PDF chuẩn in ấn', N'Chương 1: Làm quen InDesign', N'Bài 1: Tạo tài liệu nhiều trang', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80'),
('K13-C004-06', 'CAT-004', 6, 'T2', N'Motion Graphics với After Effects', N'Trung cấp', 1090000, 790000, N'Làm chữ chuyển động, đồ họa động và video giới thiệu sản phẩm bằng Adobe After Effects.', N'Bạn học keyframe, đồ thị chuyển động, shape layer, mask, track matte, hiệu ứng chữ, liên kết thuộc tính bằng expression đơn giản và quy trình làm một video giới thiệu sản phẩm ngắn từ kịch bản đến xuất file.', N'Tạo chuyển động mượt bằng đồ thị; Làm chữ và đồ họa chuyển động; Dùng mask và track matte; Hoàn thành video giới thiệu sản phẩm', N'Chương 1: Nguyên lý chuyển động', N'Bài 1: Keyframe và nhịp chuyển động', 'https://images.unsplash.com/photo-1626785774625-ddcddc3445e9?w=800&auto=format&fit=crop&q=80'),
('K13-C004-07', 'CAT-004', 7, 'T2', N'Vẽ minh họa kỹ thuật số với Procreate', N'Cơ bản', 590000, 390000, N'Vẽ minh họa trên iPad với Procreate: phác thảo, lên màu, đổ bóng và hoàn thiện tranh.', N'Khóa học hướng dẫn làm quen Procreate, chọn và tùy chỉnh cọ, quản lý layer, phác thảo bố cục, lên màu nền, đổ bóng và ánh sáng, thêm chi tiết và xuất tranh. Bạn hoàn thành ba bức minh họa theo các phong cách khác nhau.', N'Tùy chỉnh cọ vẽ trong Procreate; Phác thảo bố cục tranh minh họa; Lên màu đổ bóng và ánh sáng; Hoàn thiện và xuất tranh', N'Chương 1: Làm quen Procreate', N'Bài 1: Giao diện và bộ cọ cơ bản', 'https://images.unsplash.com/photo-1558655146-9f40138edfeb?w=800&auto=format&fit=crop&q=80'),
('K13-C004-08', 'CAT-004', 8, 'T2', N'Thiết kế thời trang cơ bản', N'Cơ bản', 890000, NULL, N'Vẽ phác thảo trang phục, hiểu chất liệu, lên ý tưởng bộ sưu tập và làm bản vẽ kỹ thuật.', N'Bạn học tỉ lệ dáng người trong vẽ thời trang, phác thảo trang phục, đặc tính các loại vải, nghiên cứu xu hướng, xây bảng cảm hứng, phát triển ý tưởng bộ sưu tập nhỏ và vẽ bản vẽ kỹ thuật để gửi xưởng may.', N'Vẽ dáng người theo tỉ lệ thời trang; Hiểu đặc tính các loại vải; Xây bảng cảm hứng cho bộ sưu tập; Vẽ bản vẽ kỹ thuật trang phục', N'Chương 1: Vẽ thời trang', N'Bài 1: Tỉ lệ dáng người trong thời trang', 'https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?w=800&auto=format&fit=crop&q=80'),
('K13-C004-09', 'CAT-004', 9, 'T2', N'Thiết kế poster và ấn phẩm sự kiện', N'Cơ bản', 490000, 350000, N'Thiết kế poster, banner và bộ ấn phẩm sự kiện có bố cục nổi bật và thông tin rõ ràng.', N'Khóa học tập trung vào bố cục và phân cấp thông tin: chọn điểm nhấn, lưới bố cục, phối chữ và hình ảnh, thiết kế một bộ ấn phẩm đồng bộ gồm poster, banner, vé mời và bài đăng mạng xã hội cho cùng một sự kiện.', N'Tạo điểm nhấn thị giác cho poster; Phân cấp thông tin rõ ràng; Dùng lưới để bố cục; Thiết kế bộ ấn phẩm sự kiện đồng bộ', N'Chương 1: Bố cục poster', N'Bài 1: Điểm nhấn và phân cấp thông tin', 'https://images.unsplash.com/photo-1572375992501-4b0892d50c69?w=800&auto=format&fit=crop&q=80'),
('K13-C004-10', 'CAT-004', 10, 'T2', N'Revit kiến trúc cơ bản', N'Trung cấp', 1290000, 990000, N'Dựng mô hình công trình theo quy trình BIM với Revit và xuất hồ sơ bản vẽ kiến trúc.', N'Bạn học tư duy BIM, thiết lập dự án Revit, dựng lưới trục, cao độ, tường, sàn, cửa, mái, cầu thang, tạo mặt cắt và mặt đứng, thống kê khối lượng và dàn trang hồ sơ bản vẽ kiến trúc từ cùng một mô hình.', N'Hiểu quy trình làm việc BIM; Dựng mô hình kiến trúc trong Revit; Tạo mặt cắt và mặt đứng; Xuất hồ sơ bản vẽ và thống kê', N'Chương 1: Tư duy BIM', N'Bài 1: BIM khác vẽ 2D truyền thống thế nào', 'https://images.unsplash.com/photo-1487958449943-2429e8be8625?w=800&auto=format&fit=crop&q=80'),
('K13-C005-01', 'CAT-005', 1, 'T2', N'Tiếng Anh giao tiếp cơ bản', N'Cơ bản', 590000, 390000, N'Tự tin giao tiếp các tình huống hằng ngày: chào hỏi, mua sắm, hỏi đường, gọi món.', N'Khóa học dành cho người mất gốc muốn nói được tiếng Anh: mỗi bài là một tình huống quen thuộc với mẫu câu, từ vựng, luyện nghe và nói theo hội thoại mẫu. Trọng tâm là phản xạ nói thay vì học thuộc ngữ pháp.', N'Chào hỏi và giới thiệu bản thân tự nhiên; Giao tiếp khi mua sắm và gọi món; Hỏi và chỉ đường; Phản xạ nói trong tình huống quen thuộc', N'Chương 1: Bắt đầu giao tiếp', N'Bài 1: Chào hỏi và giới thiệu bản thân', 'https://images.unsplash.com/photo-1522202176988-66273c2fd55f?w=800&auto=format&fit=crop&q=80'),
('K13-C005-02', 'CAT-005', 2, 'T2', N'Luyện thi IELTS 6.5+', N'Trung cấp', 1490000, 1090000, N'Chiến lược làm bài bốn kỹ năng Nghe, Nói, Đọc, Viết để đạt band 6.5 trở lên.', N'Khóa học phân tích tiêu chí chấm điểm từng kỹ năng, chiến lược làm từng dạng câu hỏi Reading và Listening, cấu trúc bài Writing Task 1 và Task 2, cách phát triển ý trong Speaking và lộ trình luyện đề trong mười hai tuần.', N'Hiểu tiêu chí chấm điểm IELTS; Làm đúng các dạng câu hỏi Reading và Listening; Viết bài Writing Task 1 và Task 2; Phát triển ý mạch lạc trong Speaking', N'Chương 1: Tổng quan IELTS', N'Bài 1: Cấu trúc bài thi và tiêu chí chấm điểm', 'https://images.unsplash.com/photo-1456513080510-7bf3a84b82f8?w=800&auto=format&fit=crop&q=80'),
('K13-C005-03', 'CAT-005', 3, 'T2', N'Luyện thi TOEIC 650+', N'Trung cấp', 990000, 690000, N'Nắm bẫy đề và chiến lược làm bảy phần thi TOEIC Listening và Reading.', N'Khóa học đi qua bảy phần của đề TOEIC, từ vựng theo chủ đề công sở, các bẫy thường gặp trong phần nghe, ngữ pháp trọng tâm của phần đọc, kỹ thuật quản lý thời gian và các đề thi thử có giải thích chi tiết.', N'Nhận diện bẫy trong phần nghe; Nắm ngữ pháp trọng tâm phần đọc; Học từ vựng TOEIC theo chủ đề; Phân bổ thời gian làm bài hợp lý', N'Chương 1: Làm quen đề thi', N'Bài 1: Cấu trúc đề TOEIC Listening và Reading', 'https://images.unsplash.com/photo-1513258496099-48168024aec0?w=800&auto=format&fit=crop&q=80'),
('K13-C005-04', 'CAT-005', 4, 'T2', N'Phát âm tiếng Anh chuẩn IPA', N'Cơ bản', 490000, NULL, N'Phát âm đúng 44 âm IPA, trọng âm, nối âm và ngữ điệu để nói rõ ràng, dễ nghe.', N'Bạn học khẩu hình của từng nguyên âm và phụ âm trong bảng IPA, các cặp âm người Việt hay nhầm, âm cuối, trọng âm từ và câu, nối âm, ngữ điệu lên xuống. Mỗi bài có phần ghi âm để tự so sánh với giọng mẫu.', N'Phát âm đúng 44 âm trong bảng IPA; Phát âm rõ âm cuối; Nhấn đúng trọng âm từ và câu; Nối âm và ngữ điệu tự nhiên', N'Chương 1: Bảng phiên âm IPA', N'Bài 1: Nguyên âm đơn và khẩu hình miệng', 'https://images.unsplash.com/photo-1546410531-bb4caa6b424d?w=800&auto=format&fit=crop&q=80'),
('K13-C005-05', 'CAT-005', 5, 'T2', N'Ngữ pháp tiếng Anh nền tảng', N'Cơ bản', 390000, 290000, N'Hệ thống lại các thì, cấu trúc câu và từ loại quan trọng nhất cho người mất gốc.', N'Khóa học trình bày ngữ pháp theo cách dễ hiểu và có ví dụ gần gũi: từ loại, cấu trúc câu, mười hai thì, câu bị động, câu điều kiện, mệnh đề quan hệ và câu tường thuật. Mỗi chủ điểm kèm bài tập có đáp án giải thích.', N'Nắm các từ loại và cấu trúc câu; Dùng đúng các thì thông dụng; Viết câu bị động và câu điều kiện; Dùng mệnh đề quan hệ chính xác', N'Chương 1: Cấu trúc câu', N'Bài 1: Chủ ngữ động từ và tân ngữ', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80'),
('K13-C005-06', 'CAT-005', 6, 'T2', N'Tiếng Anh thương mại', N'Trung cấp', 890000, NULL, N'Giao tiếp tiếng Anh trong môi trường công sở: họp, thuyết trình, đàm phán và gọi điện.', N'Khóa học dành cho người đi làm: từ vựng kinh doanh, cách điều hành và tham gia cuộc họp, trình bày số liệu, gọi điện thoại, đàm phán với đối tác và các mẫu câu lịch sự trong giao tiếp công việc với người nước ngoài.', N'Tham gia và điều hành cuộc họp bằng tiếng Anh; Trình bày số liệu và báo cáo; Gọi điện thoại công việc tự tin; Đàm phán với đối tác nước ngoài', N'Chương 1: Giao tiếp nơi công sở', N'Bài 1: Giới thiệu bản thân và công việc', 'https://images.unsplash.com/photo-1521737604893-d14cc237f11d?w=800&auto=format&fit=crop&q=80'),
('K13-C005-07', 'CAT-005', 7, 'T2', N'Tiếng Nhật sơ cấp N5', N'Cơ bản', 790000, 590000, N'Học bảng chữ Hiragana, Katakana, ngữ pháp và từ vựng nền tảng để thi JLPT N5.', N'Khóa học bắt đầu từ bảng chữ Hiragana và Katakana, sau đó học khoảng 100 chữ Hán cơ bản, từ vựng và ngữ pháp trình độ N5 qua các hội thoại đời thường, kèm chiến lược làm bài thi năng lực tiếng Nhật JLPT N5.', N'Đọc và viết Hiragana và Katakana; Nhận biết khoảng 100 chữ Hán cơ bản; Giao tiếp các câu đơn giản hằng ngày; Sẵn sàng thi JLPT N5', N'Chương 1: Bảng chữ cái', N'Bài 1: Hiragana hàng A đến hàng Sa', 'https://images.unsplash.com/photo-1528164344705-47542687000d?w=800&auto=format&fit=crop&q=80'),
('K13-C005-08', 'CAT-005', 8, 'T2', N'Tiếng Hàn sơ cấp 1', N'Cơ bản', 790000, NULL, N'Đọc viết Hangul, phát âm chuẩn và giao tiếp các tình huống cơ bản bằng tiếng Hàn.', N'Bạn học nguyên âm, phụ âm và cách ghép chữ Hangul, quy tắc phát âm, đuôi câu kính ngữ, số đếm, và hội thoại các chủ đề giới thiệu, gia đình, mua sắm, thời gian. Nội dung bám theo giáo trình sơ cấp phổ biến.', N'Đọc và viết chữ Hangul; Phát âm theo quy tắc biến âm; Dùng đuôi câu kính ngữ cơ bản; Giao tiếp các chủ đề quen thuộc', N'Chương 1: Chữ Hangul', N'Bài 1: Nguyên âm cơ bản trong tiếng Hàn', 'https://images.unsplash.com/photo-1517154421773-0529f29ea451?w=800&auto=format&fit=crop&q=80'),
('K13-C005-09', 'CAT-005', 9, 'T2', N'Tiếng Trung giao tiếp cơ bản (HSK 1-2)', N'Cơ bản', 790000, 590000, N'Phát âm pinyin và thanh điệu, học chữ Hán cơ bản và giao tiếp theo chuẩn HSK 1 đến 2.', N'Khóa học bắt đầu với hệ thống phiên âm pinyin và bốn thanh điệu, nét và bộ thủ chữ Hán, sau đó học từ vựng, mẫu câu theo chủ đề và hội thoại tương ứng trình độ HSK 1 và HSK 2.', N'Phát âm đúng pinyin và thanh điệu; Viết chữ Hán theo đúng thứ tự nét; Nắm khoảng 300 từ vựng HSK 1 và 2; Giao tiếp các tình huống hằng ngày', N'Chương 1: Phát âm tiếng Trung', N'Bài 1: Pinyin và bốn thanh điệu', 'https://images.unsplash.com/photo-1547981609-4b6bfe67ca0b?w=800&auto=format&fit=crop&q=80'),
('K13-C005-10', 'CAT-005', 10, 'T2', N'Viết email tiếng Anh chuyên nghiệp', N'Cơ bản', 390000, NULL, N'Viết email công việc rõ ràng, lịch sự: đặt lịch, báo cáo, phản hồi khiếu nại và nhắc việc.', N'Bạn học cấu trúc một email công việc, cách mở đầu và kết thúc phù hợp mức độ trang trọng, mẫu câu cho các tình huống thường gặp như đặt lịch họp, gửi báo cáo, xin lỗi, từ chối khéo, phản hồi khiếu nại và nhắc việc.', N'Viết email đúng cấu trúc; Chọn giọng văn phù hợp người nhận; Dùng mẫu câu cho tình huống thường gặp; Từ chối và phản hồi khiếu nại khéo léo', N'Chương 1: Cấu trúc email', N'Bài 1: Tiêu đề lời chào và đoạn mở đầu', 'https://images.unsplash.com/photo-1432888498266-38ffec3eaf0a?w=800&auto=format&fit=crop&q=80'),
('K13-C006-01', 'CAT-006', 1, 'T1', N'Sơ cấp cứu cơ bản tại nhà và nơi làm việc', N'Cơ bản', 390000, 290000, N'Xử lý ban đầu các tình huống thường gặp: bỏng, chảy máu, hóc dị vật, ngất và hồi sức tim phổi.', N'Khóa học hướng dẫn nguyên tắc an toàn khi sơ cứu, cách đánh giá người bị nạn, xử trí vết thương chảy máu, bỏng, gãy xương, hóc dị vật, ngất và kỹ thuật hồi sức tim phổi cơ bản. Khóa học mang tính giáo dục và không thay thế chỉ định của nhân viên y tế.', N'Đánh giá an toàn hiện trường; Sơ cứu vết thương chảy máu và bỏng; Xử trí hóc dị vật; Thực hiện hồi sức tim phổi cơ bản', N'Chương 1: Nguyên tắc sơ cứu', N'Bài 1: Đánh giá hiện trường và người bị nạn', 'https://images.unsplash.com/photo-1603398938378-e54eab446dde?w=800&auto=format&fit=crop&q=80'),
('K13-C006-02', 'CAT-006', 2, 'T1', N'Dinh dưỡng cân bằng cho người bận rộn', N'Cơ bản', 390000, NULL, N'Hiểu các nhóm chất, đọc nhãn thực phẩm và lên thực đơn lành mạnh dễ áp dụng hằng ngày.', N'Bạn học vai trò của chất đạm, chất béo, tinh bột, vitamin và khoáng chất, cách ước lượng khẩu phần bằng tay, đọc nhãn dinh dưỡng, chọn thực phẩm khi ăn ngoài và lên thực đơn tuần đơn giản. Nội dung mang tính tham khảo, người có bệnh lý nên hỏi ý kiến bác sĩ.', N'Hiểu vai trò các nhóm chất dinh dưỡng; Ước lượng khẩu phần hợp lý; Đọc nhãn dinh dưỡng trên bao bì; Lên thực đơn tuần đơn giản', N'Chương 1: Nền tảng dinh dưỡng', N'Bài 1: Các nhóm chất cơ thể cần mỗi ngày', 'https://images.unsplash.com/photo-1490645935967-10de6ba17061?w=800&auto=format&fit=crop&q=80'),
('K13-C006-03', 'CAT-006', 3, 'T1', N'Yoga cơ bản cho người mới', N'Cơ bản', 490000, 350000, N'Tập các tư thế yoga nền tảng, hơi thở và chuỗi bài tập ngắn để dẻo dai và giảm căng cơ.', N'Khóa học hướng dẫn kỹ thuật thở, khởi động, các tư thế đứng, ngồi, vặn xoắn và thư giãn cơ bản với lưu ý căn chỉnh để tránh chấn thương, sau đó ghép thành chuỗi bài tập mười lăm và ba mươi phút để tập tại nhà.', N'Thở đúng kỹ thuật khi tập; Thực hiện đúng các tư thế nền tảng; Căn chỉnh cơ thể tránh chấn thương; Tự tập chuỗi bài ngắn tại nhà', N'Chương 1: Chuẩn bị tập yoga', N'Bài 1: Hơi thở và tư thế ngồi', 'https://images.unsplash.com/photo-1544367567-0f2fcb009e0b?w=800&auto=format&fit=crop&q=80'),
('K13-C006-04', 'CAT-006', 4, 'T1', N'Tập luyện tại nhà không cần dụng cụ', N'Cơ bản', 390000, NULL, N'Chương trình tập toàn thân bằng trọng lượng cơ thể, tăng sức bền và săn chắc cơ trong 8 tuần.', N'Bạn học kỹ thuật đúng của các bài squat, lunge, chống đẩy, plank và các biến thể theo cấp độ, cách khởi động và giãn cơ, nguyên tắc tăng dần cường độ và một giáo án tám tuần có thể tập trong không gian nhỏ.', N'Thực hiện đúng kỹ thuật các bài cơ bản; Khởi động và giãn cơ đúng cách; Tăng dần cường độ an toàn; Duy trì giáo án tập tám tuần', N'Chương 1: Chuẩn bị tập luyện', N'Bài 1: Khởi động toàn thân trước khi tập', 'https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?w=800&auto=format&fit=crop&q=80'),
('K13-C006-05', 'CAT-006', 5, 'T1', N'Quản lý căng thẳng và sức khỏe tinh thần', N'Cơ bản', 490000, 350000, N'Nhận diện căng thẳng, áp dụng kỹ thuật thư giãn và xây thói quen chăm sóc sức khỏe tinh thần.', N'Khóa học giải thích cơ chế căng thẳng của cơ thể, dấu hiệu kiệt sức, các kỹ thuật thở và thư giãn cơ, cách sắp xếp công việc để giảm áp lực, xây dựng mối quan hệ hỗ trợ và khi nào nên tìm đến chuyên gia tâm lý.', N'Nhận diện dấu hiệu căng thẳng và kiệt sức; Áp dụng kỹ thuật thở và thư giãn; Sắp xếp công việc để giảm áp lực; Biết khi nào cần hỗ trợ chuyên môn', N'Chương 1: Hiểu về căng thẳng', N'Bài 1: Cơ thể phản ứng với căng thẳng thế nào', 'https://images.unsplash.com/photo-1584515933487-779824d29309?w=800&auto=format&fit=crop&q=80'),
('K13-C006-06', 'CAT-006', 6, 'T1', N'Chăm sóc giấc ngủ khoa học', N'Cơ bản', 290000, NULL, N'Hiểu nhịp sinh học, cải thiện thói quen và môi trường ngủ để ngủ sâu và đủ giấc.', N'Bạn học về chu kỳ giấc ngủ và nhịp sinh học, tác động của ánh sáng, cà phê và thiết bị điện tử, cách thiết lập giờ ngủ cố định, môi trường phòng ngủ phù hợp và các kỹ thuật thư giãn trước khi ngủ.', N'Hiểu chu kỳ giấc ngủ và nhịp sinh học; Thiết lập giờ ngủ cố định; Tối ưu môi trường phòng ngủ; Thư giãn trước khi ngủ', N'Chương 1: Giấc ngủ là gì', N'Bài 1: Các giai đoạn của một chu kỳ ngủ', 'https://images.unsplash.com/photo-1541781774459-bb2af2f05b55?w=800&auto=format&fit=crop&q=80'),
('K13-C006-07', 'CAT-006', 7, 'T1', N'Chăm sóc sức khỏe cho dân văn phòng', N'Cơ bản', 290000, 199000, N'Phòng đau cổ vai gáy, mỏi mắt và đau lưng khi ngồi máy tính nhiều giờ mỗi ngày.', N'Khóa học hướng dẫn bố trí bàn ghế và màn hình đúng công thái học, tư thế ngồi, quy tắc 20-20-20 cho mắt, các bài giãn cơ năm phút tại chỗ, cách vận động xen kẽ trong ngày và chế độ uống nước, ăn uống phù hợp.', N'Bố trí góc làm việc đúng công thái học; Giữ tư thế ngồi đúng; Giảm mỏi mắt khi dùng máy tính; Giãn cơ năm phút tại chỗ', N'Chương 1: Góc làm việc', N'Bài 1: Bố trí bàn ghế và màn hình', 'https://images.unsplash.com/photo-1504384308090-c894fdcc538d?w=800&auto=format&fit=crop&q=80'),
('K13-C006-08', 'CAT-006', 8, 'T1', N'Thiền chánh niệm cho người mới', N'Cơ bản', 290000, NULL, N'Thực hành thiền chánh niệm mỗi ngày để tập trung hơn và bình tĩnh trước áp lực.', N'Khóa học giới thiệu chánh niệm theo hướng thực hành, không gắn với tôn giáo: thiền hơi thở, quét cơ thể, đi bộ chánh niệm, quan sát cảm xúc, cách duy trì thói quen mười phút mỗi ngày và áp dụng chánh niệm trong công việc.', N'Thực hành thiền hơi thở; Quét cơ thể để thư giãn; Quan sát cảm xúc không phán xét; Duy trì thói quen thiền mỗi ngày', N'Chương 1: Bắt đầu thực hành', N'Bài 1: Chánh niệm là gì', 'https://images.unsplash.com/photo-1506126613408-eca07ce68773?w=800&auto=format&fit=crop&q=80'),
('K13-C006-09', 'CAT-006', 9, 'T1', N'Chăm sóc người cao tuổi tại nhà', N'Cơ bản', 490000, 350000, N'Chăm sóc sinh hoạt, dinh dưỡng, phòng té ngã và theo dõi sức khỏe người cao tuổi.', N'Bạn học những thay đổi sinh lý ở người cao tuổi, hỗ trợ sinh hoạt hằng ngày, chế độ dinh dưỡng, phòng té ngã, theo dõi huyết áp, đường huyết, quản lý thuốc và nhận biết dấu hiệu cần đưa đến cơ sở y tế. Khóa học không thay thế hướng dẫn của bác sĩ điều trị.', N'Hỗ trợ sinh hoạt hằng ngày an toàn; Phòng té ngã trong nhà; Theo dõi huyết áp và đường huyết; Nhận biết dấu hiệu cần đi khám', N'Chương 1: Hiểu người cao tuổi', N'Bài 1: Thay đổi sinh lý khi về già', 'https://images.unsplash.com/photo-1631815588090-d4bfec5b1ccb?w=800&auto=format&fit=crop&q=80'),
('K13-C006-10', 'CAT-006', 10, 'T1', N'Phòng ngừa bệnh mạn tính', N'Cơ bản', 390000, NULL, N'Hiểu và phòng ngừa tăng huyết áp, đái tháo đường, mỡ máu qua lối sống lành mạnh.', N'Khóa học trình bày yếu tố nguy cơ của các bệnh mạn tính thường gặp, ý nghĩa các chỉ số xét nghiệm cơ bản, vai trò của ăn uống, vận động, giấc ngủ, bỏ thuốc lá và khám sức khỏe định kỳ. Nội dung mang tính giáo dục sức khỏe.', N'Nhận biết yếu tố nguy cơ bệnh mạn tính; Hiểu các chỉ số xét nghiệm cơ bản; Xây lối sống phòng bệnh; Lập lịch khám sức khỏe định kỳ', N'Chương 1: Bệnh mạn tính', N'Bài 1: Bệnh mạn tính phổ biến ở Việt Nam', 'https://images.unsplash.com/photo-1532938911079-1b06ac7ceec7?w=800&auto=format&fit=crop&q=80');
